- = อะลิฟ, ลาม, มีม. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = บรรดาผู้เหล่านั้นอยู่บนแนวทางที่ถูกต้องจากพระเจ้าของพวกเขา และบรรดาผู้เหล่านั้นคือผู้ที่ประสบความสำเร็จ. 2:5; 31:5
- = โอ้ วงศ์วานของอิสราเอลเอ๋ย! จงรำลึกถึงความโปรดปรานของข้าพเจ้าที่ข้าพเจ้าได้ให้แก่พวกเจ้า และที่ข้าพเจ้าได้ทำให้พวกเจ้าโดดเด่นเหนือชาวโลก (ประชาชาติ) ทั้งหลาย. 2:47; 2:122
- = นั่นคือประชาชาติที่ล่วงลับไปแล้ว มันจะได้รับสิ่งที่มันได้ขวนขวายไว้ และพวกเจ้าจะได้รับสิ่งที่พวกเจ้าได้ขวนขวายไว้ และพวกเจ้าจะไม่ถูกสอบสวนเกี่ยวกับสิ่งที่พวกเขาได้กระทำ. 2:134; 2:141
- = พวกเขาจะพำนักอยู่ในนั้นอย่างถาวร การลงโทษจะไม่ถูกผ่อนปรนแก่พวกเขา และพวกเขาจะไม่ถูกผัดผ่อน. 2:162; 3:88
- = ยกเว้นบรรดาผู้ที่กลับเนื้อกลับตัวหลังจากนั้น และปรับปรุงแก้ไขให้ดีขึ้น แท้จริงอัลลอฮ์เป็นผู้ทรงอภัยโทษ ผู้ทรงเมตตาเสมอ. 3:89; 24:5
- = และบรรดาผู้ที่ปฏิเสธศรัทธาและปฏิเสธสัญญาณต่าง ๆ ของเรา ชนเหล่านั้นคือชาวนรก. 5:10; 5:86
- = และไม่มีสัญญาณใดจากสัญญาณต่าง ๆ แห่งพระเจ้าของพวกเขามายังพวกเขา เว้นแต่พวกเขาจะผินหลังให้แก่มัน. 6:4; 36:46
- = และแน่นอน ได้มีการเย้ยหยันบรรดาร่อซูลมาก่อนหน้าเจ้าแล้ว แต่ผู้ที่เย้ยหยันเหล่านั้นถูกห้อมล้อมด้วยสิ่งที่พวกเขาเคยเย้ยหยันมัน. 6:10; 21:41
- = จงกล่าวเถิด "แท้จริงฉันกลัวการลงโทษในวันอันยิ่งใหญ่ หากฉันฝ่าฝืนพระเจ้าของฉัน." 6:15; 39:13
- = ดังนั้นแผ่นดินไหวได้คร่าพวกเขา แล้วพวกเขากลายเป็นซากศพนอนพังพาบอยู่ในบ้านของพวกเขา. 7:78; 7:91
- = แล้วเขาได้โยนไม้เท้าของเขา และมันก็กลายเป็นงูตัวใหญ่ที่ชัดเจน. 7:107; 26:32
- = และเขาได้ดึงมือของเขาออกมา แล้วมันก็กลายเป็นสีขาวสว่างแก่ผู้ที่มองดู. 7:108; 26:33
- = พวกเขากล่าวว่า "เราศรัทธาต่อพระเจ้าแห่งสากลโลก." 7:121; 26:47
- = พระเจ้าแห่งมูซาและฮารูน. 7:122; 26:48
- = และข้าจะให้เวลาพวกเขา แท้จริงอุบายของข้านั้นแข็งแรง. 7:183; 68:45
- = พระองค์คือผู้ทรงส่งร่อซูลของพระองค์พร้อมด้วยแนวทางที่ถูกต้องและศาสนาแห่งสัจธรรม เพื่อพระองค์จะทรงให้มันเหนือกว่าศาสนาทั้งหมด แม้พวกตั้งภาคีจะเกลียดชังก็ตาม. 9:33; 61:9
- = โอ้ นบีเอ๋ย! จงต่อสู้กับบรรดาผู้ปฏิเสธศรัทธาและบรรดามุนาฟิกีน และจงแข็งกร้าวต่อพวกเขา และที่พำนักของพวกเขาคือนรกญะฮันนัม และมันเป็นที่กลับไปที่ชั่วช้ายิ่ง. 9:73; 66:9
- = และพวกเขากล่าวว่า "คำสัญญานี้เมื่อใดเล่า หากพวกท่านเป็นผู้สัตย์จริง?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = และแน่นอน เราได้ส่งมูซามาพร้อมด้วยสัญญาณต่าง ๆ ของเราและอำนาจอันชัดแจ้ง. 11:96; 40:23
- = และแน่นอน เราได้ให้คัมภีร์แก่มูซา แต่ได้เกิดการขัดแย้งกันขึ้นในนั้น และหากมิใช่พระดำรัสหนึ่งซึ่งได้บันทึกไว้ก่อนแล้วจากพระเจ้าของเจ้า แน่นอนก็คงถูกตัดสินระหว่างพวกเขา และแท้จริงพวกเขานั้นอยู่ในความสงสัยยิ่งนักเกี่ยวกับมัน. 11:110; 41:45
- = นั่นไม่ใช่เรื่องยากแก่อัลลอฮ์. 14:20; 35:17
- = "ดังนั้นเมื่อข้าได้ทำให้เขาสมบูรณ์ และได้เป่าวิญญาณของข้าเข้าไปในเขา พวกเจ้าจงกราบลงต่อเขา." 15:29; 38:72
- = ดังนั้นบรรดามะลาอิกะฮ์ได้กราบลงทั้งหมด. 15:30; 38:73
- = (อัลลอฮ์) ตรัสว่า "ดังนั้นเจ้าจงออกไปจากมัน เพราะแท้จริงเจ้าเป็นผู้ถูกขับไล่." 15:34; 38:77
- = (อิบลีส) กล่าวว่า "ข้าแต่พระเจ้าของข้าพระองค์! ดังนั้นขอพระองค์ทรงผัดผ่อนให้แก่ข้าพระองค์จนถึงวันเวลาที่พวกเขาจะถูกให้ฟื้นคืนชีพ." 15:36; 38:79
- = (อัลลอฮ์) ตรัสว่า "ดังนั้นแท้จริงเจ้าอยู่ในหมู่ผู้ที่ถูกผัดผ่อน." 15:37; 38:80
- = จนกระทั่งถึงวันเวลาแห่งการกำหนด." 15:38; 38:81
- = เว้นแต่ปวงบ่าวของพระองค์ในหมู่พวกเขาที่พระองค์ทรงคัดเลือกให้บริสุทธิ์. 15:40; 38:83
- = แท้จริงบรรดาผู้ยำเกรงจะอยู่ในสวนสวรรค์มากหลายและตาน้ำพุ. 15:45; 51:15
- = เขากล่าวว่า "แล้วธุระของพวกท่านเล่า โอ้ บรรดาผู้ถูกส่งมา?" 15:57; 51:31
- = พวกเขากล่าวว่า "แท้จริงเราถูกส่งมายังหมู่ชนผู้กระทำผิด." 15:58; 51:32
- = บรรดาผู้ศรัทธาและไม่ปนเปื้อนความศรัทธาของพวกเขาด้วยความอธรรม ชนเหล่านั้นจะได้รับความปลอดภัย และพวกเขาคือผู้ที่ได้รับแนวทางอันถูกต้อง. 16:42; 29:59
- = เพื่อพวกเขาจะปฏิเสธสิ่งที่เราได้ให้แก่พวกเขา แล้วพวกเจ้าจงรื่นรมย์เถิด แล้วพวกเจ้าจะได้รู้. 16:55; 30:34
- = แล้วเขาได้เดินทางไปตามทางหนึ่ง. 18:89; 18:92
- = จงไปหาฟิรเอาน์ เพราะแท้จริงเขาเป็นผู้ละเมิดเกินขอบเขต. 20:24; 79:17
- = และบรรดาผู้ที่รักษาทวารของพวกเขา. 23:5; 70:29
- = เว้นแต่แก่บรรดาภริยาของพวกเขาหรือสิ่งที่มือขวาของพวกเขาครอบครองไว้ เพราะพวกเขาจะไม่ถูกตำหนิ. 23:6; 70:30
- = ดังนั้นผู้ใดแสวงหาสิ่งที่เกินกว่านั้น ชนเหล่านั้นคือผู้ละเมิดขอบเขต. 23:7; 70:31
- = และบรรดาผู้ที่รักษาสิ่งที่ได้รับมอบหมายให้ดูแลและสัญญาของพวกเขา. 23:8; 70:32
- = เขากล่าวว่า "ข้าแต่พระเจ้าของข้าพระองค์! ขอพระองค์ทรงช่วยเหลือข้าพระองค์ด้วย เพราะพวกเขาปฏิเสธข้าพระองค์." 23:26; 23:39
- = ตอ, ซีน, มีม. 26:1; 28:1
- = เหล่านี้คือโองการทั้งหลายแห่งคัมภีร์อันชัดแจ้ง. 26:2; 28:2
- = แท้จริงในนั้นมีสัญญาณอันยิ่งใหญ่ แต่ส่วนใหญ่ของพวกเขาไม่ศรัทธา. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = และแท้จริงพระเจ้าของเจ้า แน่นอนพระองค์เป็นผู้ทรงอำนาจ ผู้ทรงเมตตาเสมอ. 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = และเราได้จมน้ำตายพวกอื่น. 26:66; 37:82
- = แท้จริงฉันคือร่อซูลผู้ซื่อสัตย์สำหรับพวกท่าน. 26:107; 26:125; 26:143; 26:162; 26:178
- = ดังนั้นพวกเจ้าจงยำเกรงอัลลอฮ์และจงเชื่อฟังฉัน. 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = และฉันมิได้ขอค่าตอบแทนในการนี้จากพวกท่าน ค่าตอบแทนของฉันอยู่ที่พระเจ้าแห่งสากลโลกเท่านั้น. 26:109; 26:127; 26:145; 26:164; 26:180
- = ในสวนสวรรค์มากหลายและตาน้ำพุ. 26:147; 44:52
- = พวกเขากล่าวว่า "แท้จริงท่านเป็นเพียงคนหนึ่งในหมู่ผู้ถูกอาคม." 26:153; 26:185
- = เว้นแต่ภริยาของเขา – เราได้กำหนดไว้แล้วว่า นางจะอยู่ในหมู่ผู้ถูกทิ้งไว้ข้างหลัง. 26:171; 37:135
- = แล้วเราได้ทำลายพวกอื่น. 26:172; 37:136
- = และเราได้โปรยหินลงมาบนพวกเขา แล้วหินที่ตกใส่ผู้ถูกตักเตือนนั้นช่างชั่วช้าเสียนี่กระไร! 26:173; 27:58
- = แล้วพวกเขายังขอให้เร่งการลงโทษอีกหรือ? 26:204; 37:176
- = บรรดาผู้ที่ดำรงการละหมาดและจ่ายซะกาต และพวกเขายืนหยัดในวันปรโลก. 27:3; 31:4
- = และจงรำลึกถึงวันที่พระองค์จะทรงเรียกพวกเขา แล้วตรัสว่า "ไหนเล่าบรรดาภาคีของข้าที่พวกเจ้ากล่าวอ้าง?" 28:62; 28:74
- = และบรรพบุรุษของเราเล่า? 37:17; 56:48
- = และพวกเขาจะหันเข้าหากัน ซักถามกันและกัน. 37:27; 52:25
- = เว้นแต่ปวงบ่าวของอัลลอฮ์ผู้บริสุทธิ์ใจ. 37:40; 37:74; 37:128; 37:160
- = ในสวนสวรรค์แห่งความสุขสำราญ. 37:43; 56:12
- = และเราได้ปล่อยทิ้งไว้ (เกียรติคุณ) แก่เขาในหมู่คนรุ่นหลัง: 37:78; 37:108; 37:129
- = แท้จริงเราประทานรางวัลเช่นนั้นแก่ผู้กระทำความดี. 37:80; 37:121; 37:131; 77:44
- = แท้จริงเขาคือคนหนึ่งในหมู่ปวงบ่าวผู้ศรัทธาของเรา. 37:81; 37:111; 37:132
- = เกิดอะไรขึ้นแก่พวกเจ้า? ทำไมพวกเจ้าจึงตัดสินเช่นนั้น? 37:154; 68:36
- = อัลกุรอานนี้มิใช่สิ่งอื่นใด นอกจากเป็นการตักเตือนแก่ประชาชาติทั้งหลาย. 38:87; 81:27
- = การประทานคัมภีร์นี้มาจากอัลลอฮ์ ผู้ทรงอำนาจ ผู้ทรงปรีชาญาณ. 39:1; 45:2; 46:2
- = ฮา, มีม. 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = ขอสาบานต่อคัมภีร์อันชัดแจ้ง. 43:2; 44:2
- = ดังนั้นเจ้าจงปล่อยพวกเขาให้จมอยู่ในการพูดไร้สาระและความสนุกสนาน จนกว่าพวกเขาจะได้พบกับวันของพวกเขา ซึ่งพวกเขาถูกสัญญาไว้. 43:83; 70:42
- = (จะมีเสียงกล่าวแก่พวกเขา) "จงกินและจงดื่มอย่างสุขสบาย เพราะสิ่งที่พวกเจ้าได้กระทำไว้." 52:19; 77:43
- = หรือเจ้าขอค่าตอบแทนจากพวกเขา ดังนั้นพวกเขาจึงเป็นหนี้สินหนัก? 52:40; 68:46
- = หรือว่าพวกเขารู้ความเร้นลับ ดังนั้นพวกเขาจึงบันทึกไว้? 52:41; 68:47
- = และการลงโทษของข้าและการตักเตือนของข้าเป็นอย่างไร! 54:16; 54:21; 54:30
- = และแน่นอน เราได้ทำให้อัลกุรอานง่ายต่อการรำลึก ดังนั้นมีผู้ใดที่จะรำลึกบ้างไหม? 54:17; 54:22; 54:32; 54:40
- = ดังนั้น ด้วยความโปรดปรานแห่งพระเจ้าของเจ้าทั้งสอง เจ้าทั้งสองจะปฏิเสธสิ่งใด? 55:13; 55:16; 55:18; 55:21; 55:23; 55:25; 55:28; 55:30; 55:32; 55:34; 55:36; 55:38; 55:40; 55:42; 55:45; 55:47; 55:49; 55:51; 55:53; 55:55; 55:57; 55:59; 55:61; 55:63; 55:65; 55:67; 55:69; 55:71; 55:73; 55:75; 55:77
- = กลุ่มชนจำนวนมากจากรุ่นก่อน ๆ. 56:13; 56:39
- = และเรากลายเป็นผู้ถูกพราก? 56:67; 68:27
- = ดังนั้นเจ้าจงสดุดีพระนามของพระเจ้าของเจ้าผู้ยิ่งใหญ่ที่สุด. 56:74; 56:96; 69:52
- = (อัลกุรอาน) เป็นการประทานลงมาจากพระเจ้าแห่งสากลโลก. 56:80; 69:43
- = สิ่งที่อยู่ในชั้นฟ้าทั้งหลายและสิ่งที่อยู่ในแผ่นดินต่างสดุดีแด่อัลลอฮ์ และพระองค์เป็นผู้ทรงอำนาจ ผู้ทรงปรีชาญาณ. 59:1; 61:1
- = เมื่อโองการทั้งหลายของเราถูกอ่านแก่เขา เขากล่าวว่า "นิทานสอนใจของคนสมัยก่อน." 68:15; 83:13
- = แล้วเขาจะอยู่ในชีวิตที่พึงใจ. 69:21; 101:7
- = ในสวนสวรรค์ชั้นสูง. 69:22; 88:10
- = และเขาไม่สนับสนุนให้อาหารแก่คนยากจนขัดสน. 69:34; 107:3
- = แท้จริงอัลกุรอานนี้คือคำกล่าวของร่อซูลผู้มีเกียรติ. 69:40; 81:19
- = แท้จริงนี่คือข้อตักเตือน และผู้ใดประสงค์ก็พึงถือเอาทางไปสู่พระเจ้าของเขา. 73:19; 76:29
- = ดังนั้นผู้ใดประสงค์ก็ให้เขารำลึก. 74:55; 80:12
