- แน่นอนบรรดาผู้ที่กล่าวว่า แท้จริงอัลลอฮ์คืออัลมะซีหฺบุตรของมัรยัมนั้นได้ปฏิเสธศรัทธาแล้ว จงกล่าวเถิด... (لَّقَدْ كَفَرَ الَّذِينَ قَالُوا إِنَّ اللَّهَ هُوَ الْمَسِيحُ ابْنُ مَرْيَمَ قُلْ) 5:17; 5:72
- เจ้าไม่สามารถทำให้คนตาบอดได้ยิน (ความจริง) จากการหลงผิดของพวกเขาได้ เจ้าจะทำให้ได้ยินเฉพาะผู้ที่ศรัทธาต่อสัญญาณต่าง ๆ ของเราเท่านั้น แล้วพวกเขาก็เป็นผู้ยอมจำนน (مُسْلِمُونَ) (الْعُمْيِ عَن ضَلَالَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِآيَاتِنَا فَهُم مُّسْلِمُونَ) 27:81; 30:53
- อุปมาชีวิตในโลกนี้เปรียบเสมือนน้ำที่เราหลั่งลงมาจากฟากฟ้า แล้วพืชผลของแผ่นดินก็คลุกเคล้ากับมัน... (مَثَلُ الْحَيَاةِ الدُّنْيَا كَمَاءٍ أَنزَلْنَاهُ مِنَ السَّمَاءِ فَاخْتَلَطَ بِهِ نَبَاتُ الْأَرْضِ) 10:24; 18:45
- ในนั้น (เรือ) จงบรรทุกจากทุกชนิดเป็นคู่ ๆ และครอบครัวของเจ้า เว้นแต่ผู้ที่พระดำรัสได้กำหนดไว้ก่อนแล้ว... (فِيهَا مِن كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ الْقَوْلُ) 11:40; 23:27
- ฉันมิได้กล่าวแก่พวกท่านว่า ที่ฉันนั้นมีขุมทรัพย์ของอัลลอฮ์ และฉันไม่รู้เรื่องเร้นลับ และฉันมิได้กล่าวว่า... (لَّا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلَا أَعْلَمُ الْغَيْبَ وَلَا أَقُولُ) 6:50; 11:31
- แท้จริงอัลลอฮ์ทรงเป็นผู้มีพระคุณแก่ปวงมนุษย์ แต่ส่วนมากของมนุษย์ไม่ขอบคุณ (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ) 2:243; 40:61
- และไม่มีสัญญาณใดจากสัญญาณต่าง ๆ ของพระเจ้าของพวกเขามายังพวกเขา เว้นแต่พวกเขาจะผินหลังให้มัน (وَمَا تَأْتِيهِم مِّنْ آيَةٍ مِّنْ آيَاتِ رَبِّهِمْ إِلَّا كَانُوا عَنْهَا مُعْرِضِينَ) 6:4; 36:46
- และจงยำเกรงวันหนึ่งซึ่งไม่มีชีวิตใดจะตอบแทนสิ่งใดแทนชีวิตอื่นได้ และการขอให้ช่วยเหลือใด ๆ ก็จะไม่ถูกรับจากมัน (وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا) 2:48; 2:123
- แท้จริงเจ้าไม่สามารถทำให้ผู้ตายได้ยิน และไม่สามารถทำให้คนหูหนวกได้ยินเสียงเรียกร้อง เมื่อพวกเขาหันหลังกลับ (إِنَّكَ لَا تُسْمِعُ الْمَوْتَى وَلَا تُسْمِعُ الصُّمَّ الدُّعَاءَ إِذَا وَلَّوْا مُدْبِرِينَ) 27:80; 30:52
- ถูกห้ามแก่พวกเจ้าแล้ว (การบริโภค) สัตว์ที่ตายเอง เลือด เนื้อสุกร และสัตว์ที่ถูกเชือดด้วยนามอื่นจากอัลลอฮ์ (حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ) 5:3; 16:115
- สิ่งที่อยู่ในชั้นฟ้าทั้งหลายและแผ่นดินต่างแซ่ซ้องสดุดีแด่อัลลอฮ์ และพระองค์คือผู้ทรงอำนาจ ผู้ทรงปรีชาญาณ (سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ) 59:1; 61:1
- นอกจากผู้ที่สำนึกผิดหลังจากนั้น และปรับปรุงแก้ไข (ตนเอง) แท้จริงอัลลอฮ์เป็นผู้ทรงอภัย ผู้ทรงเมตตาเสมอ (إِلَّا الَّذِينَ تَابُوا مِن بَعْدِ ذَلِكَ وَأَصْلَحُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ) 3:89; 24:5
- (สิ่งที่) บรรดานะบีได้รับจากพระเจ้าของพวกเขา เราไม่แบ่งแยกระหว่างผู้ใดในหมู่พวกเขา และเราเป็นผู้ยอมจำนนต่อพระองค์ (مُسْلِمُونَ) (النَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ) 2:136; 3:84
- (ถูกส่งมา) จากพระเจ้าของเจ้า เพื่อเจ้าจะได้ตักเตือนหมู่ชนหนึ่งซึ่งไม่มีผู้ตักเตือนคนใดมาหาพวกเขาก่อนหน้าเจ้า หวังว่าพวกเขา... (مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّا أَتَاهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ) 28:46; 32:3
- โอ้ นบีเอ๋ย จงต่อสู้กับพวกปฏิเสธศรัทธาและพวกกลับกลอก และจงแข็งกร้าวกับพวกเขา ที่พำนักของพวกเขาคือนรกญะฮันนัม และมันเป็นทางกลับที่ชั่วช้ายิ่ง! (يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ) 9:73; 66:9
- แท้จริงพระเจ้าของเจ้าจะทรงตัดสินระหว่างพวกเขาในวันกิยามะฮ์ ในสิ่งที่พวกเขาเคยขัดแย้งกัน (إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 10:93; 45:17
- เขากล่าวว่า โอ้พระเจ้าของข้าพระองค์ ขอพระองค์ทรงให้มีสัญญาณหนึ่งแก่ข้าพระองค์เถิด พระองค์ตรัสว่า สัญญาณของเจ้าคือเจ้าจะไม่พูดกับผู้คนเป็นเวลาสามวัน (قَالَ رَبِّ اجْعَل لِّي آيَةً قَالَ آيَتُكَ أَلَّا تُكَلِّمَ النَّاسَ) 3:41; 19:10
- ดังนั้นจงผินหน้าของเจ้าไปทางมัสยิดอัลฮะรอมเถิด และพวกเจ้าจงผินหน้าไปทางนั้น ณ ที่ใดก็ตามที่พวกเจ้าอยู่ (فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ) 2:144; 2:150
- โอ้ วงศ์วานของอิสรออีลเอ๋ย จงรำลึกถึงความโปรดปรานของข้าที่ข้าได้ให้แก่พวกเจ้า และที่ข้าได้ให้พวกเจ้าโดดเด่นเหนือประชาชาติทั้งหลาย (يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ) 2:47; 2:122
- โคสาวเจ็ดตัวที่อ้วนพี ถูกกินโดยโคสาวเจ็ดตัวที่ผอมแห้ง และรวงข้าวเจ็ดรวงที่เขียวสด และรวงอื่นที่แห้ง... (سَبْعَ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنبُلَاتٍ خُضْرٍ وَأُخَرَ يَابِسَاتٍ) 12:43; 12:46
- และทุก ๆ ประชาชาตินั้นมีกำหนดเวลา เมื่อกำหนดเวลาของพวกเขามาถึงแล้ว พวกเขาจะไม่ล่าช้าไปสักชั่วโมงหนึ่ง และไม่รุดหน้าไป (وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49
- (สัตว์ที่) ถูกเชือดด้วยนามอื่นจากอัลลอฮ์ แต่ผู้ใดถูกบังคับ (ด้วยความหิวโหย) โดยไม่เป็นผู้ละเมิดและไม่เกินขอบเขต แล้วไซร้... (أُهِلَّ لِغَيْرِ اللَّهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ) 6:145; 16:115
- และเมื่อมีผู้กล่าวแก่พวกเขาว่า จงปฏิบัติตามสิ่งที่อัลลอฮ์ได้ทรงประทานลงมาเถิด พวกเขาก็กล่าวว่า มิได้ เราจะปฏิบัติตามสิ่งที่เราได้พบเห็นจากบรรพบุรุษของเรา (وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا) 2:170; 31:21
- เขากล่าวว่า โอ้ประชาชนของฉันเอ๋ย จงเคารพภักดีต่ออัลลอฮ์เถิด ไม่มีพระเจ้าอื่นใดสำหรับพวกท่านนอกจากพระองค์ แล้วพวกท่านไม่ยำเกรงบ้างหรือ? (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23
