- และบรรดาผู้ศรัทธาและกระทำความดีทั้งหลาย จะถูกนำเข้าสู่สวนสวรรค์หลายแห่ง ซึ่งมีแม่น้ำหลายสายไหลผ่านเบื้องล่าง (وَأُدْخِلَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 14:23; 22:14; 22:23; 47:12
- เขากล่าวว่า "โอ้ หมู่ชนของฉัน! จงเคารพภักดีอัลลอฮฺเถิด ไม่มีพระเจ้าอื่นใดสำหรับพวกท่านนอกจากพระองค์ พวกท่านมิใช่หรือ?" (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23
- ทรัพย์สินของพวกเขาและลูกๆ ของพวกเขาจะไม่ช่วยพวกเขาให้รอดพ้นจากอัลลอฮฺได้แต่อย่างใด และชนเหล่านั้นคือ (لَن تُغْنِيَ عَنْهُمْ أَمْوَالُهُمْ وَلَا أَوْلَادُهُم مِّنَ اللَّهِ شَيْئًا وَأُولَئِكَ) 3:10; 3:116; 58:17
- สวนสวรรค์หลายแห่ง ซึ่งมีแม่น้ำหลายสายไหลผ่านเบื้องล่าง พวกเขาจะพำนักอยู่ในนั้นตลอดกาล และนั่นคือชัยชนะอันยิ่งใหญ่ (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ) 4:13; 9:89
- ยังมิได้มีข่าวคราวของบรรดาผู้ที่มาก่อนพวกเขามายังพวกเขาดอกหรือ – หมู่ชนของนูห์ และอ๊าด และซะมูด? (أَلَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ) 9:70; 14:9
- ใครคือผู้ช่วยเหลือของฉันไปยังอัลลอฮฺ? บรรดาสาวกกล่าวว่า "เราคือผู้ช่วยเหลือของอัลลอฮฺ เราศรัทธาแล้ว" (مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ آمَنَّا) 3:52; 61:14
- พระเจ้าของเจ้านั้น พระองค์ทรงรู้ดียิ่งว่า ผู้ใดหลงจากทางของพระองค์ และพระองค์ทรงรู้ดียิ่งในบรรดาผู้ได้รับแนวทางที่ถูกต้อง (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ) 16:125; 68:7
- นั้นก็เพราะว่าอัลลอฮฺคือพระเจ้าผู้ทรงสัจจะ และแท้จริงสิ่งที่พวกเขาเรียกร้องขออื่นจากพระองค์นั้นคือความเท็จ (ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ) 22:62; 31:30
- และผู้ใดเชื่อฟังอัลลอฮฺและร่อซูลของพระองค์ พระองค์จะทรงให้เขาเข้าสวนสวรรค์หลายแห่ง ซึ่งมีแม่น้ำหลายสายไหลผ่านเบื้องล่าง (وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 4:13; 48:17
- แท้จริง พระองค์ทรงห้ามแก่พวกเจ้าเฉพาะซากสัตว์ เลือด เนื้อสุกร และสิ่งที่ถูกเซ่น ( slaughter) (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- ว่า พวกเจ้าอย่าเคารพภักดีผู้ใดนอกจากอัลลอฮฺ แท้จริงฉันกลัวแทนพวกเจ้าถึงการลงโทษในวันหนึ่ง (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- นั่นคือส่วนหนึ่งจากข่าวเร้นลับ ซึ่งเราได้วะฮีแก่เจ้า และเจ้ามิได้อยู่กับพวกเขา ณ ขณะนั้น (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- และพวกเจ้าประหลาดใจหรือว่า ได้มีข้อเตือนสติจากพระเจ้าของพวกเจ้ามายังพวกเจ้า โดยผ่านชายคนหนึ่งจากพวกเจ้า เพื่อตักเตือนพวกเจ้า? (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- จงกล่าวเถิด "แท้จริงฉันถูกห้ามแล้ว จากการเคารพภักดีต่อสิ่งที่พวกเจ้าวิงวอนขออื่นจากอัลลอฮฺ" (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- นอกจากแก่คู่ครองของพวกเขา หรือสิ่งที่มือขวาของพวกเขาครอบครอง – แท้จริงพวกเขาไม่เป็นที่ตำหนิ (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- เพราะว่าอัลลอฮฺทรงให้กลางคืนคาบเกี่ยวเข้าไปในกลางวัน และทรงให้กลางวันคาบเกี่ยวเข้าไปในกลางคืน (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- ไฟ (กองหนึ่ง) และเขาได้กล่าวแก่ครอบครัวของเขาว่า "จงพักอยู่ก่อนเถิด แท้จริงฉันเห็นไฟ บางทีฉันอาจจะนำบางอย่างมาให้พวกท่าน" (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- เขากล่าวว่า "ฉันดีกว่าเขา; ท่านสร้างฉันจากไฟ และสร้างเขาจากดิน" (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- และเมื่อมีการกล่าวแก่พวกเขาว่า "จงมาสู่สิ่งที่อัลลอฮฺได้ทรงประทานลงมา และสู่ร่อซูลเถิด" พวกเขาก็กล่าว (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- และอย่าเศร้าโศกเพื่อพวกเขา และอย่าคับแค้นใจ ต่อสิ่งที่พวกเขาวางอุบาย (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- และหากอัลลอฮฺทรงให้ความทุกข์ยากแก่เจ้า ก็ไม่มีผู้ใดปลดเปลื้องมันได้นอกจากพระองค์; และหาก (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- ก่อนหน้าพวกเขา (มี) หลายศตวรรษ ซึ่งพวกเขาเดินทางไปมาในที่พำนักของพวกเขา แท้จริงในนั้นมีสัญญาณมากหลาย (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- และเราได้ทำให้หัวใจของพวกเขามีที่ปิดกั้น มิให้พวกเขาเข้าใจอัลกุรอาน และในหูของพวกเขามีความหนวก และหาก (พวกเขาเรียกเจ้า) (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- บรรดาร่อซูลของพวกเขาได้มายังพวกเขาพร้อมด้วยหลักฐานอันชัดเจน แต่อัลลอฮฺมิได้ทรงอธรรมแก่พวกเขา แต่ว่าพวกเขานั้นอธรรมแก่ตัวของพวกเขาเอง (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- และในแผ่นดิน และพวกเจ้าไม่มีผู้คุ้มครองหรือผู้ช่วยเหลืออื่นจากอัลลอฮฺ (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- แล้วพวกเจ้าจะถูกนำกลับไปยังพระผู้ทรงรอบรู้ในสิ่งเร้นลับและสิ่งเปิดเผย แล้วพระองค์จะทรงแจ้งแก่พวกเจ้าถึงสิ่งที่พวกเจ้ากระทำ (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- กลางคืน เพื่อพวกเจ้าจะได้พักผ่อนในนั้น และกลางวันเพื่อให้มองเห็น แท้จริงในนั้นมีสัญญาณมากหลายสำหรับหมู่ชน (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- และแน่นอน มันจะเพิ่มพูนให้แก่พวกเขาส่วนมาก ซึ่งสิ่งที่ถูกประทานลงมาแก่เจ้าจากพระเจ้าของเจ้า คือการละเมิดและการปฏิเสธศรัทธา (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- เขากล่าวว่า "โอ้หมู่ชนของฉัน! พวกท่านเห็นแล้วมิใช่หรือ? หากฉันอยู่บนหลักฐานอันชัดแจ้งจากพระเจ้าของฉัน และพระองค์ทรงประทาน (ความเมตตา) แก่ฉัน" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- และพวกเขากล่าวว่า "ทำไมสัญญาณหนึ่งจากพระเจ้าของเขาจึงมิถูกประทานลงมาแก่เขาเล่า?" จงกล่าวเถิด "แท้จริง" (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- ก่อนที่วันหนึ่งจะมาถึง ซึ่งจะไม่มีทางหันกลับให้พ้นจากอัลลอฮฺได้ (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- นั่นคือความโปรดปรานของอัลลอฮฺ ซึ่งพระองค์ทรงประทานให้แก่ผู้ที่พระองค์ทรงประสงค์ และอัลลอฮฺนั้นคือผู้ทรงโปรดปรานอันยิ่งใหญ่ (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
- และแท้จริงสำหรับพวกเจ้าในปศุสัตว์นั้นมีข้อเตือนใจ; เราทำให้พวกเจ้าดื่มจากสิ่งที่อยู่ในท้องของมัน (وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ) 16:66; 23:21
- และว่า แท้จริงมันคือความจริงจากพระเจ้าของพวกเขา; และอัลลอฮฺมิได้ทรงเพิกเฉยต่อสิ่งที่พวกเขากระทำ (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
- จากเบื้องหน้าพวกเขาและเบื้องหลังพวกเขา (เพื่อว่า) พวกเจ้าอย่าเคารพภักดีผู้ใดนอกจากอัลลอฮฺ (مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ) 41:14; 46:21
- แท้จริงพวกเจ้ามีเพศสัมพันธ์กับผู้ชายด้วยความใคร่ แทนที่จะเป็นผู้หญิง; แต่ว่าพวกเจ้าเป็นหมู่ชนที่ (ประพฤติล่วงเกิน) (إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ) 7:81; 27:55
- พวกเขาจะพำนักอยู่ในนั้นตลอดกาล ตราบเท่าที่ชั้นฟ้าทั้งหลายและแผ่นดินยังคงอยู่ เว้นแต่ที่พระเจ้าของเจ้าทรงประสงค์ (خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ) 11:107; 11:108
- ผู้ที่อยู่ในชั้นฟ้าทั้งหลายและผู้ที่อยู่ในแผ่นดิน เว้นแต่ผู้ที่อัลลอฮฺทรงประสงค์ (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
