- แท้จริง นี่คือข้อเตือนสติ; ดังนั้นผู้ใดประสงค์ ก็จงเลือกเอาทางสู่พระเจ้าของเขา (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- และผู้ใดขอบคุณ แท้จริงเขาขอบคุณเพื่อตัวของเขาเอง; และผู้ใดเนรคุณ แท้จริง (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- บรรดาผู้ที่ดำรงการละหมาด และบริจาคซะกาต และพวกเขาแน่นอนเชื่อมั่นในวันปรโลก (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- (ใน) อิบรอฮีม อิสมาอีล อิสหาก ยะอ์กูบ และบรรดาวงศ์วาน (ของพวกเขา) และสิ่งที่ถูกประทานแก่มูซาและอีซา (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- เป็นกลุ่มๆ จนกระทั่งเมื่อพวกเขามาถึงมัน ประตูต่างๆ ของมันจะถูกเปิดออก และยามรักษาการณ์ของมันจะกล่าวแก่พวกเขา (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- อัลลอฮฺจะไม่ทรงเอาโทษแก่พวกเจ้าด้วยคำพูดไร้สาระในการสาบานของพวกเจ้า แต่พระองค์จะทรงเอาโทษแก่พวกเจ้าในสิ่งที่ (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- (ด้วย) ความเมตตา พวกเขาดีใจกับมัน; และหากความชั่วร้ายประสบพวกเขา ด้วยสิ่งที่มือของพวกเขาได้นำส่งไว้ก่อน (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- ซึ่งมีแม่น้ำหลายสายไหลผ่านเบื้องล่าง พวกเขาจะพำนักอยู่ในนั้นตลอดกาล และรางวัลของผู้กระทำความดีช่างดีเยี่ยม! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- อัลลอฮฺทรงรู้สิ่งที่อยู่ในชั้นฟ้าทั้งหลายและสิ่งที่อยู่ในแผ่นดิน; และอัลลอฮฺ (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- จงเชื่อฟังอัลลอฮฺและเชื่อฟังร่อซูลเถิด; แต่หากพวกเจ้าผินหลังให้ (การเชื่อฟัง) แท้จริงหน้าที่ของเขาคือ (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- สำหรับพวกเขาคือรางวัลของพวกเขา ณ ที่พระเจ้าของพวกเขา; ไม่มีความหวาดกลัวใดๆ แก่พวกเขา และพวกเขา (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- และพวกเขากล่าวว่า "เมื่อเราได้กลายเป็นกระดูกและเศษธุลีแล้ว เราจะถูกให้ฟื้นคืนชีพอีกอย่างแน่นอนหรือ?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- และพวกเขาจะไม่พบผู้คุ้มครองหรือผู้ช่วยเหลืออื่นจากอัลลอฮฺ (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- ท่านพำนักอยู่นานเท่าใด? เขากล่าวว่า "ฉันพำนักอยู่หนึ่งวัน หรือเพียงบางส่วนของวัน" เขากล่าวว่า (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- ตลอดกาลนานจนถึงวันกิยามะฮ์ ใครคือพระเจ้าอื่นจากอัลลอฮฺที่จะนำมาให้พวกเจ้า? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- ผู้ใดกระทำความดี ไม่ว่าจะเป็นเพศชายหรือเพศหญิง และเขาเป็นผู้ศรัทธา (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- บรรดาผู้ที่ห้ามปรามจากทางของอัลลอฮฺ และต้องการทำให้ทางนั้นคดเคี้ยว และพวกเขาปฏิเสธศรัทธาต่อวันปรโลก (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- ณ ที่ใดก็ตามที่พวกท่านประสงค์ (จงกินเถิด) และอย่าเข้าใกล้ต้นไม้ต้นนี้ มิฉะนั้นพวกท่านจะกลายเป็นผู้อธรรม (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- จงกล่าวเถิด "โอ้หมู่ชนของฉัน! จงปฏิบัติตามสภาพของพวกท่านเถิด แท้จริงฉันก็จะปฏิบัติ; แล้วพวกท่านจะรู้" (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- แท้จริงบรรดาผู้ขาดทุน คือผู้ที่ทำให้ตัวของพวกเขาและครอบครัวของพวกเขาขาดทุนในวันกิยามะฮ์ พึงรู้เถิด! (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- ผู้ใดได้แนวทางที่ถูกต้อง ก็ย่อมได้แนวทางนั้นเพื่อตัวของเขาเอง; และผู้ใดหลงทาง ก็ย่อมหลงทางเพื่อตัวของเขาเอง; และไม่มีผู้ใด (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- และบรรดาผู้ปฏิเสธศรัทธากล่าวว่า "ทำไมสัญญาณหนึ่งจากพระเจ้าของเขาจึงมิถูกประทานลงมาแก่เขาเล่า?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- ผู้ทรงทำให้กลางคืนเป็นที่พักผ่อนแก่พวกเจ้า และกลางวันให้มองเห็น (เป็นเวลา) แท้จริง (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- ก่อนที่วันหนึ่งจะมาถึง ซึ่งในวันนั้นจะไม่มีการซื้อขาย และไม่มีการ (มิตรภาพ) (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- เพื่อพวกเขาจะได้ใคร่ครวญ; สหายของพวกเขา (มุฮัมมัด) ไม่ใช่คนบ้า; เขามิได้เป็นอื่นใดนอกจากผู้ตักเตือน (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- พวกเขาจะพำนักอยู่ในนั้นตลอดกาล; การลงโทษจะไม่ถูกลดหย่อนแก่พวกเขา และพวกเขาจะไม่ถูกผ่อนผัน (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- อย่าทอดสายตาทั้งสองของเจ้าไปยังสิ่งที่เราได้ให้ความเพลิดเพลินแก่คู่สมรสบางคนของพวกเขา (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- และอย่าทำให้ประชาชนขาดแคลนในสิ่งของของพวกเขา และอย่าก่อความเสียหายในแผ่นดิน (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- และความศานติจงมีแด่เขา ในวันที่เขาถือกำเนิด และวันที่เขาตาย และวันที่เขาถูกฟื้นคืนชีพ (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- โอ้หมู่ชนของฉัน! จงปฏิบัติตามสภาพของพวกท่านเถิด แท้จริงฉันก็จะปฏิบัติ; แล้วพวกท่านจะรู้ว่าใคร (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- และไม่บังควรแก่ร่อซูลที่จะนำสัญญาณใดๆ เว้นแต่ด้วยอนุมัติของอัลลอฮฺ (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- แล้วทุกชีวิตจะได้รับผลตอบแทนโดยครบถ้วน ตามที่มันได้กระทำไว้ และพวกเขาจะไม่ถูกอธรรม (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- เพศชายหรือเพศหญิง และเขาเป็นผู้ศรัทธา – ชนเหล่านั้นจะได้เข้าสวนสวรรค์ (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- พระองค์มิได้ทรงยึดบุตร และไม่มีผู้มีส่วนร่วมในอำนาจปกครองของพระองค์ (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- และผู้ใดที่อัลลอฮฺทรงนำทาง เขาก็จะเป็นผู้ได้รับแนวทางที่ถูกต้อง; และผู้ใดที่พระองค์ทรงให้หลงทาง เจ้าจะไม่พบ (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- จงดูเถิดว่า พวกเขาได้ยกอุทาหรณ์แก่เจ้าอย่างไร? พวกเขาหลงทางแล้ว และไม่สามารถหาทางได้ (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- จงกล่าวเถิด "แท้จริงฉันกลัว หากฉันฝ่าฝืนพระเจ้าของฉัน ต่อการลงโทษในวันอันยิ่งใหญ่" (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- ครั้นแล้ว (เมื่อทั้งสองกินผลไม้จากต้นไม้นั้น) อวัยวะอันน่าละอายของทั้งสองก็ปรากฏแก่ทั้งสอง และทั้งสองก็เริ่มนำใบไม้จากสวนสวรรค์มาปกปิด (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- และจงวิงวอนขอต่อผู้ที่พวกเจ้าสามารถ (วิงวอนขอ) ได้ นอกจากอัลลอฮฺ หากพวกเจ้าเป็นผู้สัตย์จริง (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- สิ่งที่อยู่ในแผ่นดินทั้งหมด และมีอีกเช่นนั้นกับมัน เพื่อจะใช้มันไถ่ตัว (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- จงยึดถือสิ่งที่เราได้ให้แก่พวกเจ้าด้วยความเข้มแข็ง และจงรำลึกถึงสิ่งที่อยู่ในนั้น – หวังว่าพวกเจ้าจะเกรงกลัว (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- พวกเจ้ามีเพศสัมพันธ์กับบรรดาผู้ชาย (ด้วยความใคร่) ซึ่งไม่มีผู้ใดในหมู่มนุษย์ทั่วโลกกระทำมาก่อนพวกเจ้า? (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- และเป็นกรรมสิทธิ์ของอัลลอฮฺ คือสิ่งที่อยู่ในชั้นฟ้าทั้งหลายและสิ่งที่อยู่ในแผ่นดิน; และอัลลอฮฺนั้นเป็นผู้ทรง (วะลี) (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- ผล(กรรม) ชั่วที่พวกเขาได้กระทำไว้ ได้ประสบแก่พวกเขา และสิ่งที่พวกเขาเคยเยาะเย้ย ก็ห้อมล้อมพวกเขา (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- (โดย) ร่อซูลคนหนึ่งจากพวกเจ้า ซึ่งเขาจะอ่านโองการต่างๆ ของเราแก่พวกเจ้า และจะทำให้พวกเจ้าบริสุทธิ์ และจะสอนคัมภีร์และความรอบรู้แก่พวกเจ้า (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- จากนั้น ก็ได้ผุดน้ำขึ้นมาสิบสองตาน้ำ; แน่นอนแต่ละกลุ่ม (เผ่า) ย่อมรู้แหล่งน้ำดื่มของตน (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- นอกจากแต่การเดาเท่านั้น; แท้จริงการเดาไม่เป็นประโยชน์ต่อความจริงแต่อย่างใด (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- ดังนั้นเมื่อเราได้ทำให้เขาสมบูรณ์ (ตามสัดส่วน) และได้เป่าวิญญาณของเราเข้าไปในเขา แล้วพวกเจ้าจงก้มลงสุญูดต่อเขา (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
- ผู้ใดที่จะมีบั้นปลายแห่งที่อยู่นี้? แท้จริงบรรดาผู้อธรรมจะไม่ประสบความสำเร็จ (مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ) 6:135; 28:37
