- แก่บรรดาผู้ศรัทธาชายและบรรดาผู้ศรัทธาหญิง – คือสวนสวรรค์หลายแห่ง ซึ่งมีแม่น้ำหลายสายไหลผ่านเบื้องล่าง โดยพำนักอยู่ในนั้นตลอดกาล (الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 9:72; 48:5
