- พวกเขาวิงวอนขอต่ออัลลอฮฺ โดยเป็นผู้บริสุทธิ์ใจในศาสนาต่อพระองค์; และเมื่อพระองค์ทรงช่วยพวกเขาให้รอดพ้นขึ้นบก (دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ) 29:65; 31:32
