- และพระองค์ทรงให้สิ่งมีชีวิตออกมาจากสิ่งที่ไร้ชีวิต และทรงให้สิ่งที่ไร้ชีวิตออกมาจากสิ่งมีชีวิต (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- และผู้ใดมิได้ตัดสินตามที่อัลลอฮฺได้ประทานลงมา ชนเหล่านั้นคือ... (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- พระองค์ทรงสร้างชั้นฟ้าทั้งหลายและแผ่นดิน และสิ่งที่อยู่ระหว่างทั้งสอง ในระยะเวลา 6 วัน (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- แท้จริง อัลลอฮฺทรงเป็นผู้ทรงโปรดปรานแก่มนุษย์ แต่ว่าส่วนมาก... (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- อัลลอฮฺมิได้ทรงอธรรมแก่พวกเขา แต่ว่าพวกเขาต่างหากที่อธรรมแก่ตัวของพวกเขาเอง (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- พระองค์จะทรงลบล้างความชั่วทั้งหลายของพวกเจ้า และจะทรงให้พวกเจ้าเข้าสวนสวรรค์หลายแห่ง ซึ่งมีแม่น้ำหลายสายไหลอยู่เบื้องล่างของมัน (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- พระองค์ทรงห้ามพวกเจ้าซึ่งสัตว์ที่ตายเอง และเลือด และเนื้อสุกร และสิ่งที่ถูกเชือดด้วยนามอื่นจากอัลลอฮฺ (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- แท้จริงฉันกลัวว่า หากฉันฝ่าฝืนพระเจ้าของฉัน ฉันจะได้รับการลงโทษในวันอันยิ่งใหญ่ (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- เว้นแต่หลังจากที่ความรู้ได้มายังพวกเขาแล้ว ทั้งนี้เพราะความอิจฉาริษยาระหว่างพวกเขา (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- และพวกเขาดำรงไว้ซึ่งการละหมาด และบริจาคส่วนหนึ่งจากสิ่งที่เราได้ให้ปัจจัยยังชีพแก่พวกเขา ทั้งอย่างลับและเปิดเผย (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- อื่นจากอัลลอฮฺ สิ่งที่ไม่ให้ประโยชน์แก่เราและไม่ให้โทษแก่เรา (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- พวกเขาศรัทธาต่อสิ่งที่ถูกประทานลงมาแก่เจ้า และสิ่งที่ถูกประทานลงมาก่อนเจ้า (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- เจ้ามิได้เห็นดอกหรือว่า อัลลอฮฺทรงประทานน้ำลงมาจากฟากฟ้า (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- เมื่อพระองค์ทรงกำหนดกิจการใดแล้ว พระองค์ก็จะกล่าวแก่มันว่า "จงเป็น" แล้วมันก็จะเป็น (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- และยังมะดยัน (เราได้ส่ง) ชุอัยบ์ พี่น้องของพวกเขา เขากล่าวว่า "โอ้หมู่ชนของฉันเอ๋ย! จงเคารพภักดีต่ออัลลอฮฺเถิด" (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- นั่นคือส่วนหนึ่งจากข่าวเร้นลับ ซึ่งเราจะเปิดเผยแก่เจ้า และเจ้ามิได้อยู่กับพวกเขา... (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- เมื่อถึงกำหนดเวลาของพวกเขา พวกเขาจะไม่สามารถขอให้ช้าลงไปได้สักชั่วโมงหนึ่ง และไม่สามารถขอให้เร็วขึ้นได้ (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- และพวกเจ้าอย่าตามบรรดารอยเท้าของชัยฏอน แท้จริงมันคือศัตรูที่ชัดแจ้งของพวกเจ้า (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- และในหมู่มนุษย์มีผู้ที่โต้เถียงกันในเรื่องของอัลลอฮฺ โดยปราศจากความรู้ (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- อัลลอฮฺทรงประทานให้แก่ผู้ที่พระองค์ทรงประสงค์ และอัลลอฮฺนั้นเป็นผู้ทรงโปรดปรานอันยิ่งใหญ่ (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَالَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- ทุกชีวิตจะได้รับการตอบแทนอย่างเต็มที่ตามที่ตนได้กระทำไว้ และพวกเขาจะไม่ถูกอธรรม (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- และพวกเจ้าอย่าฆ่าชีวิตที่อัลลอฮฺทรงห้ามไว้ เว้นแต่ด้วยสิทธิอันชอบธรรม (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- เมื่อพระองค์ทรงกำหนดกิจการใดแล้ว พระองค์ก็จะกล่าวแก่มันว่า "จงเป็น" (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- พวกเจ้าจงเข้าไปในประตูทั้งหลายของนรก โดยเป็นผู้พำนักอยู่ในนั้นตลอดกาล และที่พำนักของผู้หยิ่งยโสนั้นช่างเลวร้ายยิ่ง! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- เจ้ามิได้มองดูบรรดาผู้ที่ได้รับส่วนหนึ่งจากคัมภีร์ดอกหรือ? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- สำหรับพวกเขาคือสวนสวรรค์หลายแห่ง ซึ่งมีแม่น้ำหลายสายไหลอยู่เบื้องล่างของมัน โดยพวกเขาจะพำนักอยู่ในนั้นตลอดกาล (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- โอ้หมู่ชนของฉันเอ๋ย! จงทำงานตามสภาพของพวกท่าน แท้จริงฉันก็จะทำงาน (ตามสภาพของฉัน) แล้วพวกท่านจะได้รู้ (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- ผู้ใดฝ่าฝืนอัลลอฮฺและรอซูลของพระองค์ แท้จริงสำหรับเขาคือไฟนรกญะฮันนัม โดยเขาจะพำนักอยู่ในนั้นตลอดกาล (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- บนหัวใจของพวกเขามีผ้าคลุมหลายชั้น เพื่อมิให้พวกเขาเข้าใจมัน และในหูของพวกเขามีความหนวก (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- ไม่มีเมืองใดที่ผู้ตักเตือนได้มายังเมืองนั้น เว้นแต่บรรดาผู้ฟุ่มเฟือยของมันจะกล่าวว่า "แท้จริงพวกเรา..." (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- พวกเขากล่าวว่า "จงวิงวอนต่อพระเจ้าของท่านให้แก่เรา เพื่อพระองค์จะทรงแจกแจงแก่เราว่า มันคืออะไร" (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- พวกเขาจะกล่าวว่า "อัลลอฮฺ" จงกล่าวเถิด "บรรดาสรรเสริญเป็นของอัลลอฮฺ" แต่ว่าส่วนมากของพวกเขาไม่... (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- และไม่ปรากฏคำตอบของหมู่ชนของเขา นอกจากพวกเขากล่าวว่า "จงขับไล่พวกเขาออกไป..." (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- เบื้องล่างของมันมีแม่น้ำหลายสายไหลผ่าน โดยพวกเขาจะพำนักอยู่ในนั้นตลอดกาล นั่นคือชัยชนะอันยิ่งใหญ่ (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- ชนเหล่านั้นอยู่บนแนวทางที่ถูกต้องจากพระเจ้าของพวกเขา และชนเหล่านั้นคือผู้ที่ประสบความสำเร็จ (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- ผู้ที่การลงโทษอันน่าอับอายจะมาถึงเขา และการลงโทษอันคงทนจะครอบงำเขา (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- พวกเจ้าจงท่องเที่ยวไปในแผ่นดิน แล้วจงดูว่า บั้นปลายของบรรดาผู้ปฏิเสธนั้นเป็นอย่างไร (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- พวกเขาจะไม่ปรารถนามันตลอดกาล เนื่องด้วยสิ่งที่มือของพวกเขาได้ประกอบไว้ก่อน และอัลลอฮฺทรงรู้ดีต่อบรรดาผู้อธรรม (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- พระองค์ทรงรู้ดียิ่งต่อผู้ที่หลงทางจากแนวทางของพระองค์ และพระองค์ทรงรู้ดียิ่ง... (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- แท้จริง อัลลอฮฺคือพระเจ้าของฉัน และพระเจ้าของพวกเจ้า ดังนั้นพวกเจ้าจงเคารพภักดีต่อพระองค์เถิด นี่คือแนวทางอันเที่ยงตรง (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- ทรงเป็นผู้โปรดปรานแก่มนุษย์ แต่ว่าส่วนมากของพวกเขาไม่ขอบคุณ (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- ชั้นฟ้าทั้งหลายและแผ่นดินและสิ่งที่อยู่ระหว่างทั้งสอง มิใช่เพื่อสิ่งอื่นใดนอกจากด้วยความจริง และระยะเวลาที่ถูกกำหนดไว้ (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- ดังนั้นจงปล่อยพวกเขาให้มัวเมาและเล่นสนุกไปจนกว่าพวกเขาจะได้พบกับวันของพวกเขา ซึ่งพวกเขาถูกสัญญาไว้ (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- และเมื่อพวกเขาพบบรรดาผู้ศรัทธา พวกเขาก็กล่าวว่า "เราศรัทธาแล้ว" และเมื่อพวกเขาอยู่ตามลำพัง... (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- พวกเขาดำรงไว้ซึ่งอัตเตารอตและอัลอินญีล และสิ่งที่ถูกประทานลงมาแก่พวกเขาจากพระเจ้าของพวกเขา (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- พระองค์ทรงรู้สิ่งที่อยู่เบื้องหน้าพวกเขา และสิ่งที่อยู่เบื้องหลังพวกเขา และพวกเขาไม่สามารถหยั่งรู้ได้... (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- และพระองค์คือผู้ทรงสร้างชั้นฟ้าทั้งหลายและแผ่นดินในระยะเวลา 6 วัน (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- แท้จริงในนั้นมีสัญญาณหนึ่งสำหรับพวกเจ้า หากพวกเจ้าเป็นผู้ศรัทธา (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- และอะไรเล่าที่ขัดขวางมนุษย์มิให้ศรัทธา เมื่อแนวทางที่ถูกต้องได้มายังพวกเขาแล้ว? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- และพวกเขาได้ตั้งภาคีคู่เคียงแก่อัลลอฮฺ เพื่อที่จะให้หลงจากแนวทางของพระองค์ จงกล่าวเถิด "จงรื่นเริงกันเถิด..." (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- และพวกเขาประหลาดใจว่า ได้มีผู้ตักเตือนคนหนึ่งจากหมู่พวกเขามายังพวกเขา และบรรดาผู้ปฏิเสธศรัทธากล่าวว่า "นี่คือ..." (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- แท้จริง พระเจ้าของเจ้านั้นทรงรู้ดียิ่งต่อผู้ที่หลงทางจากแนวทางของพระองค์ (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- เช่นเดียวกับผู้ที่บริจาคทรัพย์สินของเขาเพื่อโอ้อวดแก่มนุษย์ และไม่ศรัทธาต่ออัลลอฮฺ (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- จงบริจาคส่วนหนึ่งจากสิ่งที่เราได้ให้ปัจจัยยังชีพแก่พวกเจ้า ก่อนที่...จะมาถึง (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- พระองค์ทรงทำให้สิ่งที่อยู่ในชั้นฟ้าทั้งหลายและสิ่งที่อยู่ในแผ่นดินเป็นประโยชน์แก่พวกเจ้า (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- และแท้จริงพวกเราอยู่ในความสงสัยเกี่ยวกับสิ่งที่พวกท่านเรียกร้องเราไปสู่มัน (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- แท้จริง พระเจ้าของเจ้าทรงแผ่ปัจจัยยังชีพให้กว้างขวางแก่ผู้ที่พระองค์ทรงประสงค์ และทรงให้คับแคบ แท้จริงพระองค์... (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- พระเจ้าแห่งชั้นฟ้าทั้งหลายและแผ่นดิน และสิ่งที่อยู่ระหว่างทั้งสอง หากพวกเจ้าเป็นผู้ศรัทธามั่นคง (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- เราได้ศรัทธาต่ออัลลอฮฺ และสิ่งที่ถูกประทานลงมาแก่เรา และสิ่งที่ถูกประทานลงมาแก่... (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- และเสียงกัมปนาทได้คร่าบรรดาผู้อธรรม แล้วพวกเขาก็กลายเป็นผู้ยอบกายลงในบ้านเรือนของพวกเขา (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- ดังนั้นไม่เป็นบาปใดๆ แก่พวกเจ้า ในสิ่งที่พวกนางได้กระทำไปเกี่ยวกับตัวของพวกนาง (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- พระเจ้าของเจ้านั้นทรงรู้ดียิ่งต่อผู้ที่หลงทางจากแนวทางของพระองค์ และพระองค์... (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- ด้วยวิญญาณ (วะฮีย์) ตามพระบัญชาของพระองค์ แก่ผู้ที่พระองค์ทรงประสงค์จากปวงบ่าวของพระองค์ (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- และเราได้ประทานหลักฐานอันชัดเจนแก่อีซา อิบนุมัรยัม และเราได้สนับสนุนเขาด้วยวิญญาณบริสุทธิ์ (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- เพื่อพระองค์จะทรงตัดสินระหว่างพวกเขาในวันกิยามะฮ์ ในสิ่งที่พวกเขาเคยขัดแย้งกัน (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- เราได้ทำให้ส่วนบนของมันเป็นส่วนล่าง และเราได้ให้หินจากดินเผาตกหล่นลงมาบนพวกเขา (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- มันเท่าเทียมกันแก่พวกเขา เจ้าจะตักเตือนพวกเขาหรือไม่ตักเตือน พวกเขาก็ไม่ศรัทธา (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- อื่นจากมนุษย์ทั้งหลาย ดังนั้นพวกท่านจงปรารถนาความตายเถิด หากพวกท่านเป็นผู้สัตย์จริง (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- จงเคารพภักดีต่ออัลลอฮฺเถิด พวกท่านไม่มีพระเจ้าอื่นใดนอกเหนือจากพระองค์ แล้วพวกท่านไม่ยำเกรงหรือ? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- และหากเราจะให้เจ้าได้เห็นบางส่วนที่เราได้สัญญาแก่พวกเขา หรือเราจะให้เจ้าเสียชีวิต ดังนั้นยังเราเท่านั้นคือทางกลับของพวกเขา... (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- พวกเขากล่าวว่า "เมื่อเราตายไปแล้ว และเรากลายเป็นดินและกระดูกแล้ว เราจะถูกฟื้นคืนชีพอีกกระนั้นหรือ?" (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- แท้จริงความโปรดปรานนั้นอยู่ในพระหัตถ์ของอัลลอฮฺ พระองค์จะประทานมันแก่ผู้ที่พระองค์ทรงประสงค์ และอัลลอฮฺ... (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- ยังพระผู้ทรงรอบรู้ในสิ่งเร้นลับและสิ่งที่เปิดเผย แล้วพระองค์จะทรงแจ้งแก่พวกเจ้าในสิ่งที่พวกเจ้ากระทำกัน (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- โอ้บรรดาผู้ศรัทธาเอ๋ย! จงรำลึกถึงความโปรดปรานของอัลลอฮฺที่มีต่อพวกเจ้า ขณะที่... (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- และเรามิได้ส่งผู้ใดมาเป็นรอซูลก่อนเจ้า นอกจากเป็นบุรุษ ซึ่งเราได้วะฮีย์แก่พวกเขา (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- พระองค์จะทรงลบล้างความผิดของเขา และจะทรงให้เขาเข้าสวนสวรรค์หลายแห่ง ซึ่งมีแม่น้ำหลายสายไหลอยู่เบื้องล่างของมัน (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- ผู้ป่วย หรืออยู่ในการเดินทาง ดังนั้นให้ชดใช้ในวันอื่น (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- พวกเขามิได้ปฏิบัติตามสิ่งใดนอกจากความนึกคิด และพวกเขามิได้ทำสิ่งใดนอกจากคาดเดาเท่านั้น (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- แน่นอน สำหรับพวกเจ้านั้นมีแบบอย่างที่ดีแล้ว สำหรับผู้ที่หวัง (การพบ) อัลลอฮฺและวันปรโลก (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- และเรามิได้สร้างชั้นฟ้าทั้งหลายและแผ่นดิน และสิ่งที่อยู่ระหว่างทั้งสอง เว้นแต่ด้วยความจริง (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- จงสอดมือของเจ้าเข้าไปในอกเสื้อของเจ้า มันจะออกมาขาวปราศจากโรค (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- พระองค์ทรงเลือกสรรมนุษย์ด้วยความเมตตาของพระองค์แก่ผู้ที่พระองค์ทรงประสงค์ และอัลลอฮฺนั้นเป็นผู้ทรงโปรดปรานอันยิ่งใหญ่ (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- เจ้ามิรู้ดอกหรือว่า อัลลอฮฺนั้นทรงมีอำนาจเด็ดขาดเหนือชั้นฟ้าทั้งหลายและแผ่นดิน? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- และสิ่งที่พวกเจ้าได้บริจาคล่วงหน้าไว้เพื่อตัวของพวกเจ้าเองจากความดี พวกเจ้าจะพบมัน ณ ที่อัลลอฮฺ (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- และจากที่ไหนก็ตามที่เจ้าออกไป ก็จงผินหน้าของเจ้าไปทางมัสยิดอัลหะรอม (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- พวกนั้นได้ล่วงลับไปแล้วก่อน และเจ้าจะไม่พบการเปลี่ยนแปลงในแนวทางของอัลลอฮฺ (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- พระผู้ทรงเป็นเจ้าของสิ่งที่อยู่ในชั้นฟ้าทั้งหลายและสิ่งที่อยู่ในแผ่นดิน (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- และไม่มีหญิงใดจะตั้งครรภ์หรือคลอด เว้นแต่ด้วยความรอบรู้ของพระองค์ (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- กลางคืน และพระองค์ทรงทำให้ดวงอาทิตย์และดวงจันทร์เป็นประโยชน์ (ทุกสิ่ง) โคจรไปตามกำหนดเวลา (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- เบื้องล่างของมันมีแม่น้ำหลายสายไหลผ่าน โดยพวกเขาจะพำนักอยู่ในนั้นตลอดกาล และนั่นคือรางวัลของ... (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- เขากล่าวว่า "เปล่าหรอก จิตใจของพวกเจ้าได้ตกแต่งเรื่องหนึ่งให้แก่พวกเจ้า ดังนั้นความอดทนเป็นสิ่งที่สวยงาม" (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- สิ่งที่อยู่ในชั้นฟ้าทั้งหลายและสิ่งที่อยู่ในแผ่นดิน และแท้จริงอัลลอฮฺ... (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- และไม่มีรอซูลคนใดมายังพวกเขา นอกจากพวกเขาจะเยาะเย้ยถากถางเขา (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- พวกเขากล่าวว่า "โอ้มูซาเอ๋ย! ท่านจะโยนก่อน หรือว่าพวกเราจะเป็นผู้โยน?" (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- พระองค์ทรงทำให้พวกเจ้าตาย และในหมู่พวกเจ้ามีผู้ที่ถูกนำกลับไปสู่วัยชราที่เลวทราม เพื่อว่า... (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- สำหรับพวกเขาคือสวนสวรรค์หลายแห่ง ณ ที่พระเจ้าของพวกเขา ซึ่งมีแม่น้ำหลายสายไหลอยู่เบื้องล่างของมัน โดยพวกเขาจะพำนักอยู่ในนั้นตลอดกาล (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- และเราได้ทำให้บนหัวใจของพวกเขามีผ้าคลุมหลายชั้น เพื่อมิให้พวกเขาเข้าใจมัน และในหูของพวกเขา... (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- แท้จริงสัญญาของอัลลอฮฺนั้นเป็นจริง แต่ว่าส่วนมากของพวกเขาไม่รู้ (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- นั่นก็เพราะว่าพวกเขาฝ่าฝืนอัลลอฮฺและรอซูลของพระองค์ และผู้ใดฝ่าฝืนอัลลอฮฺ... (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- และวันซึ่งพระองค์จะทรงเรียกพวกเขา แล้วตรัสว่า "ไหนเล่าบรรดาภาคีของข้า ซึ่งพวกเจ้าเคยอ้าง?" (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- พวกเขามิได้พิจารณาดอกหรือว่า อัลลอฮฺผู้ทรงสร้างชั้นฟ้าทั้งหลายและแผ่นดิน... (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- ผู้ทรงบังเกิดเจ้าจากดิน แล้วจากน้ำอสุจิ แล้วจาก... (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- พวกเขาจะกล่าวว่า "ข้าแต่พระเจ้าของเรา! ถ้าเพียงพระองค์ทรงส่งรอซูลมายังเรา เพื่อเราจะได้ปฏิบัติตามสัญญาณทั้งหลายของพระองค์" (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- แล้วยังพระเจ้าของพวกเขาคือการกลับคืนของพวกเขา แล้วพระองค์จะทรงแจ้งแก่พวกเขาในสิ่งที่พวกเขาเคยกระทำ (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- พวกเขาไม่มีความรู้ใดๆ ในเรื่องนั้น พวกเขามิได้ปฏิบัติตามสิ่งใดนอกจาก... (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- แท้จริงเราได้พบว่าบรรพบุรุษของเราอยู่บนแนวทางหนึ่ง และแท้จริงเราจะดำเนินตามรอยเท้าของพวกเขา (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- บรรดาผู้ที่ได้รับคัมภีร์ มิได้แตกแยกกันเว้นแต่หลังจากที่ได้มีความรู้มายังพวกเขาแล้ว... (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- และจงรำลึกเมื่ออิบรอฮีมกล่าวว่า "ข้าแต่พระเจ้าของข้า! ขอพระองค์ทรงทำให้เมืองนี้เป็นเมืองที่ปลอดภัย" (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- และพระองค์ทรงทำให้แก่พวกเจ้า ซึ่งการได้ยิน และการเห็น และหัวใจ แต่ส่วนน้อยเท่านั้นที่พวกเจ้าขอบคุณ (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- บรรดาผู้ที่โต้เถียงกันในสัญญาณทั้งหลายของอัลลอฮฺ โดยปราศจากหลักฐานใดๆ ที่มายังพวกเขา (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- ดังนั้นพวกเจ้าจงปฏิบัติตามแนวทางของอิบรอฮีม ผู้ใฝ่หาความจริง และเขามิได้อยู่ในหมู่ผู้ตั้งภาคี (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- และจงรำลึกขณะที่เราได้ช่วยพวกเจ้าให้พ้นจากวงศ์วานของฟิรเอาน์ ซึ่งพวกเขาได้บังคับพวกเจ้าให้รับการทรมานอันสาหัส (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- นั่นคือศาสนาอันเที่ยงตรง แต่ว่าส่วนมากของมนุษย์ไม่รู้ (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- เจ้ามิได้พิจารณาดอกหรือว่า อัลลอฮฺทรงทำให้สิ่งที่อยู่ใน...เป็นประโยชน์แก่พวกเจ้า? (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- บรรดาผู้ปฏิเสธศรัทธากล่าวว่า "นี่มิใช่สิ่งอื่นใด นอกจากมายากลอันชัดแจ้ง" (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- และเมื่อบรรดาโองการอันชัดแจ้งของเราถูกอ่านแก่พวกเขา บรรดาผู้ปฏิเสธศรัทธากล่าวว่า... (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- สวนสวรรค์หลากหลายแห่งความสุขสำราญ ซึ่งมีแม่น้ำหลายสายไหลอยู่เบื้องล่างของมัน โดยพวกเขาจะพำนักอยู่ในนั้นตลอดกาล (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- สิ่งที่พระองค์ทรงประสงค์ แท้จริงอัลลอฮฺนั้นเป็นผู้ทรงอานุภาพเหนือทุกสิ่ง (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- เพื่อพระองค์จะทรงอภัยโทษความผิดของพวกเจ้า และทรงผ่อนผันพวกเจ้าไปจนถึงวาระที่ถูกกำหนดไว้ (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- พวกท่านประสงค์ที่จะห้ามปรามพวกเราจากสิ่งที่บรรพบุรุษของพวกเราเคยเคารพบูชา (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- และจงรำลึกเมื่อพระเจ้าของเจ้าตรัสแก่มะลาอิกะฮ์ว่า "แท้จริงข้าจะสร้างมนุษย์จาก..." (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- และพระองค์คือผู้ทรงส่งลมเป็นข่าวดีเบื้องหน้าความเมตตาของพระองค์ (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- จงกล่าวเถิด "พวกเจ้าจงท่องเที่ยวไปในแผ่นดิน แล้วจงดูว่าบั้นปลายของ...นั้นเป็นอย่างไร" (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- แท้จริงในการสร้างชั้นฟ้าทั้งหลายและแผ่นดิน และการสับเปลี่ยนกลางคืนและกลางวันนั้น (มีสัญญาณ) (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- ผู้ใดที่จะให้อัลลอฮฺยืมหนี้ที่ดี แล้วพระองค์จะทรงเพิ่มพูนให้แก่เขา? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- ดังนั้นจงตัดสินระหว่างพวกเขาด้วยสิ่งที่อัลลอฮฺทรงประทานลงมา และอย่าปฏิบัติตามอารมณ์ต่ำของพวกเขา (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- พวกเขามิได้คอยสิ่งใด นอกจากมะลาอิกะฮ์จะมายังพวกเขา หรือพระเจ้าของเจ้าจะมา...? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- แท้จริงบรรดาผู้ที่อุปโลกน์ความเท็จต่ออัลลอฮฺนั้น พวกเขาจะไม่ประสบความสำเร็จ (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- เช่นเดียวกับสภาพของวงศ์วานของฟิรเอาน์ และบรรดาผู้ก่อนหน้าพวกเขา พวกเขาปฏิเสธสัญญาณทั้งหลายของเรา (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- และทรงแจ้งข่าวดีแก่บรรดาผู้ศรัทธาที่กระทำความดีทั้งหลายว่า สำหรับพวกเขาคือรางวัลอันยิ่งใหญ่ (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- อัลลอฮฺทรงแผ่ปัจจัยยังชีพให้แก่ผู้ที่พระองค์ทรงประสงค์จากปวงบ่าวของพระองค์ และทรงให้คับแคบ (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- และพวกเจ้าจะถูกนำกลับไปยังพระผู้ทรงรอบรู้ในสิ่งเร้นลับและสิ่งที่เปิดเผย แล้วพระองค์จะทรงแจ้งแก่พวกเจ้าในสิ่งที่พวกเจ้าเคย... (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- และบรรดาญาติใกล้ชิดนั้นบางคนมีสิทธิมากกว่าอีกบางคนในคัมภีร์ของอัลลอฮฺ (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — จำเป็น (ต้องทำ; เป็นบาปหากละทิ้ง)
- mustahabb / mandub (مستحب / مندوب) — ที่แนะนำ (ได้บุญหากทำ, ไม่เป็นบาปหากละทิ้ง)
- mubah (مباح) — เฉยๆ / ที่อนุญาต (ไม่มีบุญหรือบาป)
- makruh (مكروه) — ที่ไม่ชอบ (ถูกกีดกัน, แต่ไม่เป็นบาปหากทำ)
- haram (حرام) — ต้องห้าม (เป็นบาปหากทำ)
- halal (حلال, ที่อนุญาต / ถูกต้องตามกฎหมาย) — ครอบคลุมทั้งมุบาฮ์และมุสตะฮับ — ทุกสิ่งที่ไม่ได้ถูกห้าม
- จงเคารพภักดีต่ออัลลอฮ์เพียงผู้เดียว และขอความช่วยเหลือจากพระองค์ 1:5
- จงเคารพภักดีต่ออัลลอฮ์เพียงผู้เดียว 2:21
- อย่าตั้งภาคีใดๆ ต่ออัลลอฮ์ 2:22
- อัลลอฮ์คือผู้ทรงอภัย (ทรงรับการกลับใจ) พระองค์ทรงรับการกลับใจของอาดัม (عَلَيْهِ ٱلسَّلَامُ) 2:37
- อย่าปะปนความจริงด้วยความเท็จ และอย่าปิดบังความจริง 2:42
- จงดำรงไว้ซึ่งการละหมาด และจงจ่ายซะกาต 2:43
- จงสั่งใช้ผู้อื่นให้ทำความดี หลังจากที่ตัวท่านได้ปฏิบัติมันแล้ว 2:44
- จงขอความช่วยเหลือจากอัลลอฮ์ในทุกๆ กิจการของท่าน 2:45
- อย่าเข้าไปเกี่ยวข้องหรือแพร่กระจายการทุจริต 2:60
- อย่าขัดขวางผู้คนจากการไปยังสถานที่ประกอบพิธีกรรมทางศาสนา 2:114
- จงเคารพความศักดิ์สิทธิ์ของมัสยิด จงรักษาสถานที่ละหมาดของท่านให้สะอาดและบริสุทธิ์ 2:125
- จงรำลึกถึงอัลลอฮ์ (โดยการละหมาด การสดุดี ฯลฯ) พระองค์จะทรงรำลึกถึงพวกท่าน และจงขอบคุณพระองค์ 2:152
- จงฝึกความอดทนในยามทุกข์ยาก 2:153
- อย่าปฏิบัติตามรอยเท้าของชัยฏอน (ซาตาน) ผู้เป็นศัตรูที่ชัดแจ้ง 2:168
- อย่าปฏิบัติตามใครอย่างไร้เหตุผล 2:170
- จงรักษาและปฏิบัติตามความไว้วางใจทั้งหมด จงปฏิบัติหน้าที่ทางศาสนาของท่านด้วยความจริงใจ จงรักษาคำสาบานและพันธสัญญาของท่าน จงรักษาสัญญา โดยเฉพาะที่ให้ไว้แก่อัลลอฮ์ จงสนับสนุนผู้ขัดสนและบรรเทาความยากลำบาก จงหลีกเลี่ยงการทำบาปที่นำไปสู่การสูญเสียความโปรดปรานจากพระเจ้า อย่าให้ความเย่อหยิ่งนำท่านไปสู่ความอยุติธรรม 2:177
- ในกฎแห่งการตอบแทน (กิศาศ) นั้นมีชีวิตสำหรับพวกท่าน 2:179
- จงถือศีลอดในเดือนรอมฎอน จงปฏิบัติตามการถือศีลอดที่ถูกกำหนดไว้เพื่อให้พวกท่านเป็นผู้ยำเกรง 2:183
- จงเคารพอัลกุรอานในฐานะแหล่งชี้นำสูงสุด 2:185
- อย่ากินทรัพย์สินของกันและกันอย่างไม่เป็นธรรม และอย่าให้สินบนแก่ผู้พิพากษา (ก่อนที่จะนำเสนอคดีของท่าน) 2:188
- อย่ากดขี่ผู้อื่น ไม่ว่าจะด้วยคำพูดหรือการกระทำ อย่าเข้าสู่การต่อสู้ในฐานะผู้รุกราน แต่เพื่อป้องกันตัวเท่านั้น 2:190
- จงปกป้องเด็กกำพร้า ส่วนเรื่องเด็กกำพร้านั้น จงทำงานอย่างซื่อสัตย์ในทรัพย์สินของพวกเขา และอย่ากลืนกินทรัพย์สินของพวกเขา 2:220
- จงสำนึกผิดและขออภัยโทษต่ออัลลอฮ์ อย่ามีเพศสัมพันธ์ในช่วงมีประจำเดือน จงรักษาความสะอาดและความบริสุทธิ์ (ทั้งทางร่างกายและจิตวิญญาณ) 2:222
- จงปฏิบัติตามความรับผิดชอบของท่านที่มีต่อครอบครัว 2:233
- จงเลือกผู้นำตามความดีความชอบของพวกเขา 2:247
- อย่าบังคับในเรื่องศาสนา 2:256
- จงใช้จ่ายทรัพย์สินในการทำบุญ จงเป็นผู้ใจบุญทั้งในทรัพย์สินและเวลา 2:261
- อย่าทำให้การทำบุญของท่านเสียไปด้วยการโอ้อวดความมีน้ำใจของท่าน 2:264
- ชัยฏอน (ซาตาน) ข่มขู่พวกท่านด้วยความยากจน และสั่งใช้พวกท่านให้ทำความชั่ว (บาป) 2:268
- จงแสวงหาผู้ขัดสนและช่วยเหลือพวกเขา 2:273
- อย่าเกี่ยวข้องกับดอกเบี้ย อย่ากินทรัพย์สินที่มีดอกเบี้ย อย่ากินริบา (ดอกเบี้ย) 2:275
- จงให้เวลามากขึ้นในการชำระหนี้ หากลูกหนี้ตกอยู่ในความยากลำบาก 2:280
- จงรักษาคำพูดของท่านในธุรกรรมทางการค้า จงซื่อสัตย์ในกิจการทางการเงินของท่าน จงปฏิบัติด้วยความซื่อตรงในพันธสัญญาทั้งหมดของท่าน เมื่อท่านทำสัญญาเป็นหนี้ในช่วงเวลาที่กำหนด จงจดบันทึกไว้ จงนำพยานทุกครั้งที่ท่านทำสัญญาทางการค้า 2:282
- จงรักษาและปฏิบัติตามความไว้วางใจทั้งหมด 2:283
- จงศรัทธาต่อคัมภีร์ที่ถูกประทานลงมาและบรรดานบีทั้งหมด 2:285
- อัลลอฮ์ไม่ทรงบังคับผู้ใดเกินความสามารถของเขา พวกเขาจะได้รับการตอบแทนในสิ่งที่พวกเขาได้กระทำไว้ (ความดี) และจะถูกลงโทษในสิ่งที่พวกเขาได้กระทำไว้ (ความชั่ว) พระเจ้าไม่ทรงบังคับผู้ใดเกินความสามารถของเขา และเราก็ไม่ควรทำเช่นกัน จงไว้วางใจในแผนของอัลลอฮ์แม้ในยามยากลำบาก 2:286
- ผู้ที่รักษาสัญญาและเกรงกลัวอัลลอฮ์อย่างยิ่ง แท้จริงอัลลอฮ์ทรงรักผู้ยำเกรง 3:76
- จงประกอบพิธีฮัจญ์ หากท่านมีความสามารถ 3:97
- อย่าแตกแยกกัน 3:103
- จงสั่งใช้สิ่งที่ถูกต้อง และห้ามปรามสิ่งที่ผิด จงส่งเสริมความดีงามในชุมชนของท่าน จงเรียกร้องผู้อื่นให้รำลึกถึงอัลลอฮ์ 3:104
- และต่ออัลลอฮ์เท่านั้น ผู้ศรัทธาทั้งหลายจงมอบความไว้วางใจ 3:122
- อย่ากินริบา (ดอกเบี้ย) 3:130
- จงเชื่อฟังอัลลอฮ์และรอซูลของพระองค์ เพื่อจะได้รับความเมตตา 3:132
- อัลลอฮ์ทรงรักผู้ที่บริจาค (ในหนทางของอัลลอฮ์ – การกุศล การทำบุญ ฯลฯ) ทั้งในยามรุ่งเรืองและในยามทุกข์ยาก ผู้ที่ระงับโทสะ และผู้ที่ให้อภัยผู้อื่น 3:134
- จงระงับโทสะ 3:134
- จงอภัยให้แก่ความผิดพลาดของผู้อื่น 3:135
- อย่าพูดจาหยาบคาย จงอดทนต่อผู้ที่แตกต่างจากท่าน 3:159
- หากอัลลอฮ์ทรงช่วยเหลือพวกท่าน ก็ไม่มีใครชนะพวกท่านได้ และหากพระองค์ทรงทอดทิ้งพวกท่าน ก็ใครเล่าที่จะช่วยเหลือพวกท่านหลังจากพระองค์? 3:160
- ทุกคนจะได้ลิ้มรสความตาย และเฉพาะในวันกิยามะฮ์เท่านั้น พวกท่านจะได้รับผลตอบแทนของพวกท่านโดยครบถ้วน 3:185
- จงใคร่ครวญอย่างลึกซึ้งถึงความมหัศจรรย์ของธรรมชาติและการสร้างจักรวาลนี้ จงรู้ว่าพระเจ้าทรงสร้างจักรวาลด้วยความหมายและจุดประสงค์ 3:191
- ชายและหญิงมีผลตอบแทนเท่าเทียมกันสำหรับการกระทำของพวกเขา 3:195
- สำหรับผู้ที่เกรงกลัวพระเจ้าของพวกเขา คือสวนสวรรค์หลากหลายที่มีแม่น้ำไหลผ่านเบื้องล่าง (ในสวนสวรรค์) พวกเขาจะพำนักอยู่ในนั้นตลอดกาล เป็นการต้อนรับจากอัลลอฮ์ 3:198
- จงมุ่งมั่นเพื่อความพอพระทัยของอัลลอฮ์ในทุกการกระทำ 3:200
- จงจงรักภักดีต่อพระเจ้าของท่าน จงยำเกรงพระองค์ และอย่าตัดขาดจากเครือญาติ 4:1
- จงคืนทรัพย์สินแก่เด็กกำพร้า และอย่าเปลี่ยนเอาสิ่งเลวของท่านไปแทนที่สิ่งดีของพวกเขา และอย่ากลืนกินทรัพย์สินของพวกเขาโดยปนกับทรัพย์สินของท่าน 4:2
- จงมอบสินสอด (มะฮัร) แก่บรรดาสตรีที่ท่านแต่งงานด้วย ด้วยความเต็มใจ 4:4
- จงปกป้องสิทธิของเด็กกำพร้า 4:6
- ทรัพย์สินของผู้ตายควรได้รับการแบ่งปันในหมู่สมาชิกในครอบครัวของเขา สตรีมีสิทธิได้รับมรดก 4:7
- อย่ากลืนกินทรัพย์สินของเด็กกำพร้าอย่างไม่เป็นธรรม 4:10
- จงปฏิบัติตามคำสั่งเกี่ยวกับมรดก 4:11
- เป็นที่ต้องห้ามที่จะรับมรดกของผู้หญิงโดยขัดต่อความต้องการของพวกเธอ และพวกท่านอย่าปฏิบัติต่อพวกเธออย่างรุนแรง จงอยู่ร่วมกับพวกเธอ (ภรรยา) อย่างมีเกียรติ จงเคารพและปฏิบัติตามสิทธิของสตรี จงปฏิบัติต่อคู่สมรสของท่านด้วยความเมตตาและความเห็นอกเห็นใจ จงปฏิบัติต่อสตรีด้วยเกียรติและความยุติธรรม 4:19
- อย่าแต่งงานกับผู้ที่มีสายโลหิตเดียวกันกับท่าน 4:23
- อย่าฆ่าตัวเอง (หรือฆ่ากันเอง) แท้จริงอัลลอฮ์เป็นผู้ทรงเมตตาต่อพวกท่านเสมอ อย่ากลืนกินทรัพย์สินของกันและกันอย่างไม่เป็นธรรม 4:29
- หากพวกท่านหลีกเลี่ยงบาปใหญ่ที่ถูกห้าม อัลลอฮ์จะทรงลบล้างความผิดเล็กน้อยของพวกท่าน และจะทรงให้พวกท่านเข้าสู่ทางเข้าอันทรงเกียรติ (คือสวรรค์) 4:31
- อย่าปรารถนาในสิ่งที่อัลลอฮ์ทรงให้บางคนในหมู่พวกท่านดีเด่นกว่าคนอื่น จงหลีกเลี่ยงความอิจฉาริษยา 4:32
- บุรุษเป็นผู้ปกครองและผู้ดูแลสตรี เพราะอัลลอฮ์ทรงให้บางคนเหนือกว่าบางคน และเพราะพวกเขาได้ใช้จ่ายจากทรัพย์สินของพวกเขา (เพื่อเลี้ยงดูพวกเธอ) บุรุษเป็นผู้ปกป้องและผู้ค้ำจุนครอบครัว 4:34
- จงเคารพภักดีต่ออัลลอฮ์ และอย่าตั้งภาคีใดๆ ต่อพระองค์ จงทำดีต่อบิดามารดา ญาติพี่น้อง เด็กกำพร้า ผู้ขัดสน เพื่อนบ้าน ผู้ใกล้ชิด คนเดินทาง และผู้ที่อยู่ภายใต้การครอบครองของพวกท่าน แท้จริงอัลลอฮ์ไม่ทรงชอบผู้ที่หยิ่งผยองและโอ้อวด จงทำดีต่อผู้อื่น จงแสดงความเมตตาต่อผู้ที่อ่อนแอ จงรักษาสายสัมพันธ์ในครอบครัวและให้เกียรติญาติพี่น้อง 4:36
- อย่าเป็นคนตระหนี่ 4:37
- แท้จริงอัลลอฮ์ไม่ทรงอภัยโทษให้แก่การตั้งภาคีต่อพระองค์ แต่พระองค์ทรงอภัยโทษให้นอกเหนือจากนั้นแก่ผู้ที่พระองค์ทรงประสงค์ 4:48
- อย่าอิจฉาผู้อื่น 4:54
- แท้จริงอัลลอฮ์ทรงบัญชาพวกท่านให้คืนความไว้วางใจแก่เจ้าของของมัน และเมื่อพวกท่านตัดสินระหว่างผู้คน จงตัดสินด้วยความยุติธรรม 4:58
- จงเชื่อฟังอัลลอฮ์และรอซูลของพระองค์ และจงให้เกียรติแก่ผู้มีอำนาจในหมู่พวกท่าน 4:59
- อย่ากดขี่ผู้ที่อ่อนแอหรือเปราะบาง 4:75
- ความดีใดๆ ที่ประสบแก่พวกท่าน ย่อมมาจากอัลลอฮ์ และความชั่วใดๆ ที่ประสบแก่พวกท่าน ย่อมมาจากตัวของพวกท่านเอง 4:79
- ผู้ใดเชื่อฟังรอซูล (มุฮัมมัด ﷺ) แน่นอนเขาได้เชื่อฟังอัลลอฮ์แล้ว 4:80
- ผู้ใดช่วยเหลือในทางที่ดี เขาก็จะได้รับส่วนหนึ่งจากผลตอบแทนของมัน และผู้ใดช่วยเหลือในทางที่ชั่ว เขาก็จะได้รับส่วนหนึ่งจากบาปของมัน 4:85
- ไม่เป็นการสมควรแก่ผู้ศรัทธาที่จะฆ่าผู้ศรัทธาด้วยกัน เว้นแต่ด้วยความผิดพลาด 4:92
- ผู้ใดฆ่าผู้ศรัทธาโดยเจตนา สิ่งตอบแทนของเขาคือนรก อยู่ในนั้นตลอดกาล และอัลลอฮ์ทรงกริ้วเขาและทรงสาปแช่งเขา และได้ทรงเตรียมการลงโทษอันยิ่งใหญ่ไว้สำหรับเขา 4:93
- ผู้ใดอพยพออกจากบ้านของเขาในหนทางของอัลลอฮ์ เขาจะพบในแผ่นดินซึ่งมีที่พักพิงอันมากมายและความกว้างขวาง 4:100
- จงรักษาเวลาการละหมาดของท่าน 4:103
- อย่าสนับสนุนหรือเป็นทนายความแก่ผู้ที่ทรยศต่อความไว้วางใจของพวกเขา 4:105
- จงขออภัยโทษต่ออัลลอฮ์ แท้จริงอัลลอฮ์เป็นผู้ทรงอภัยโทษ ผู้ทรงเมตตาเสมอ 4:106
- โอ้บรรดาผู้ศรัทธาเอ๋ย! จงยืนหยัดอย่างมั่นคงเพื่อความยุติธรรม เป็นพยานเพื่ออัลลอฮ์ แม้จะเป็นปรปักษ์ต่อตัวของพวกท่านเอง หรือต่อบิดามารดาและญาติใกล้ชิด ไม่ว่าเขาจะรวยหรือจนก็ตาม อย่าล่าช้าในความยุติธรรม จงปฏิบัติทันทีในการแก้ไขความอยุติธรรม 4:135
- พวกนักต้มตุ๋นต่างหากที่พยายามจะหลอกลวงอัลลอฮ์ และพระองค์ก็ทรงหลอกลวงพวกเขา 4:142
- แท้จริงพวกนักต้มตุ๋นจะอยู่ในชั้นต่ำสุดแห่งไฟนรก และเจ้าจะไม่พบผู้ช่วยเหลือใด ๆ สำหรับพวกเขา 4:145
- อัลลอฮ์ไม่ทรงชอบให้มีการกล่าวคำหยาบคายในที่สาธารณะ เว้นแต่ผู้ที่ถูกอธรรม 4:148
- เราได้ส่งบรรดารอซูลมาในฐานะผู้แจ้งข่าวดีและผู้ตักเตือน เพื่อว่ามนุษย์จะได้ไม่มีข้ออ้างใด ๆ ต่ออัลลอฮ์ หลังจากบรรดารอซูล 4:165
- จงปฏิบัติตามสัญญาและคำมั่นสัญญาของท่าน 5:1
- จงช่วยเหลือกันและกันในความดีและความยำเกรง และอย่าช่วยเหลือกันและกันในบาปและความเป็นศัตรู 5:2
- อย่ากินสัตว์ที่ตายเอง เลือด และเนื้อหมู 5:3
- จงเป็นผู้ยุติธรรม อย่าให้ความเกลียดชังและการเป็นศัตรูของผู้อื่นทำให้พวกท่านละเลยความยุติธรรม จงเป็นผู้ยุติธรรมและเที่ยงธรรมในกิจการของท่าน จงรู้ว่าความยุติธรรมนั้นใกล้ชิดกับความยำเกรง อย่าล่าช้าในความยุติธรรม จงปฏิบัติทันทีในการแก้ไขความอยุติธรรม 5:8
- จงแสวงหาสื่อนำเข้าใกล้พระองค์ และจงต่อสู้ดิ้นรนในหนทางของพระองค์เท่าที่พวกท่านสามารถ เพื่อว่าพวกท่านจะได้รับชัยชนะ 5:35
- จงปฏิบัติตามคำสัตย์สาบานและพันธสัญญาของท่าน 5:89
- จงหลีกเลี่ยงสุราและการพนัน จงหลีกเลี่ยงสุราอย่างเด็ดขาด การพนัน การเชือดสัตว์เพื่อบูชารูปเคารพ และการเสี่ยงทายด้วยลูกศร ซึ่งทั้งหมดเป็นสิ่งโสมมประดุจผลงานของชัยฏอน 5:90
- อย่าฆ่าสัตว์ในขณะที่พวกท่านอยู่ในอิหฺรอมสำหรับฮัจญ์หรืออุมเราะฮ์ 5:95
- อย่าถามถึงสิ่งที่หากถูกเปิดเผยแก่พวกท่านแล้วอาจก่อให้เกิดความเดือดร้อนแก่พวกท่าน 5:101
- อย่าดูหมิ่นเจว็ดของผู้อื่น อย่าดูหมิ่นสิ่งที่พวกเขาเคารพสักการะอื่นจากอัลลอฮ์ มิฉะนั้นพวกเขาก็อาจจะดูหมิ่นอัลลอฮ์อย่างไม่มีความรู้ 6:108
- หากพวกท่านปฏิบัติตามคนส่วนใหญ่ในแผ่นดิน พวกเขาจะทำให้พวกท่านหลงทางจากหนทางของอัลลอฮ์ แท้จริงพวกเขาไม่ปฏิบัติตามเว้นแต่การคาดเดา และพวกเขาไม่ได้ทำอะไรนอกจากกล่าวเท็จ 6:116
- จงละทิ้งบาปทั้งหลายทั้งที่เปิดเผยและที่ปกปิด 6:120
- อย่ากินเนื้อสัตว์ที่มิได้มีการกล่าวพระนามของอัลลอฮ์บนมัน 6:121
- ผู้ใดที่อัลลอฮ์ทรงประสงค์จะชี้นำทาง พระองค์จะทรงเปิดอกของเขาเพื่ออิสลาม และผู้ใดที่พระองค์ทรงประสงค์จะปล่อยให้หลงทาง พระองค์จะทรงทำให้ทรวงอกของเขาแคบและอึดอัด 6:125
- จงเป็นผู้พอประมาณในการใช้จ่าย และหลีกเลี่ยงความฟุ่มเฟือย จงรักษาสิทธิของสรรพสิ่งทั้งหลาย 6:141
- อย่าตั้งภาคีใด ๆ ต่ออัลลอฮ์ จงทำดีต่อบิดามารดา อย่าฆ่าลูกของพวกท่านด้วยความกลัวความจน อย่าเข้าใกล้สิ่งลามกอนาจาร อย่าฆ่าชีวิตที่อัลลอฮ์ทรงห้ามไว้ เว้นแต่ด้วยเหตุอันชอบธรรม 6:151
- จงซื่อสัตย์ อย่าโกงในการค้าขายของท่าน อย่าเข้าใกล้ทรัพย์สินของเด็กกำพร้า เว้นแต่เพื่อปรับปรุงมัน และจงให้ครบเต็มทะนานและชั่งด้วยความยุติธรรม เมื่อพวกท่านพูดก็จงพูดความจริง แม้ว่าจะเป็นเรื่องเกี่ยวกับญาติที่ใกล้ชิด และจงรักษาพันธสัญญาของอัลลอฮ์ 6:152
- จงปฏิบัติตามหนทางอันเที่ยงตรงนี้ และอย่าปฏิบัติตามหนทางอื่น ๆ เพราะมันจะทำให้พวกท่านแยกออกไปจากหนทางของพระองค์ 6:153
- จงกล่าวเถิด (มุฮัมมัด) แท้จริงการละหมาดของฉัน การประกอบพิธีกรรมของฉัน การมีชีวิตของฉัน และการตายของฉัน ขอนอบน้อมแด่อัลลอฮ์พระเจ้าแห่งสากลโลก 6:162
- อย่าเป็นคนหยิ่งยโส 7:13
- อย่าให้ชัยฏอนหลอกลวงพวกท่าน 7:27
- จงกล่าวเถิด (มุฮัมมัด) พระเจ้าของฉันทรงสั่งให้มีความยุติธรรม 7:29
- จงปฏิบัติตามขอบเขตที่อัลลอฮ์ทรงกำหนดไว้ในทุกเรื่อง จงหลีกเลี่ยงการละเมิดในการพูดและการกระทำ จงกินและดื่ม แต่อย่าฟุ่มเฟือย จงแต่งกายอย่างเรียบร้อยในเวลาละหมาด 7:31
- แท้จริงพระเจ้าของพวกท่านคืออัลลอฮ์ ผู้ทรงสร้างชั้นฟ้าทั้งหลายและแผ่นดินในหกวัน แล้วพระองค์ทรงประทับบนบัลลังก์ 7:54
- จงวิงวอนต่อพระเจ้าของพวกท่านด้วยความนอบน้อมและในที่ลับ แท้จริงพระองค์ไม่ทรงชอบผู้ละเมิด 7:55
- อย่าก่อความเสียหายในแผ่นดินหลังจากที่ได้มีการจัดระเบียบแล้ว และจงวิงวอนพระองค์ด้วยความกลัวและความหวัง 7:56
- ส่วนบรรดาผู้ที่ทำความชั่วแล้วกลับใจหลังจากนั้นและศรัทธาแล้ว แท้จริงพระเจ้าของเจ้า หลังจากนั้นทรงเป็นผู้อภัย ผู้ทรงเมตตาเสมอ 7:153
- จงกล่าวเถิด (มุฮัมมัด) โอ้มนุษย์ทั้งหลาย แท้จริงฉันคือรอซูลของอัลลอฮ์มายังพวกท่านทุกคน 7:158
- พระนามอันสวยงามทั้งหลายเป็นสิทธิของอัลลอฮ์ ดังนั้นจงวิงวอนต่อพระองค์ด้วยพระนามเหล่านั้น และจงละทิ้งผู้ที่บิดเบือนพระนามของพระองค์ 7:180
- ผู้ใดที่อัลลอฮ์ทรงปล่อยให้หลงทางแล้ว ก็จะไม่มีผู้ชี้นำทางแก่เขา และพระองค์จะทรงปล่อยให้พวกเขาระเหเร่ร่อนในความละเมิดของพวกเขา 7:186
- จงให้อภัย จงสั่งใช้ความดี และจงผินหลังให้แก่ผู้โง่เขลา (คืออย่าลงโทษพวกเขา) 7:199
- จงอภัยแก่ผู้อื่นสำหรับความผิดพลาดของพวกเขา 7:199
- และหากมีอุบายใดๆ จากชัยฏอนมากระทบเจ้า จงขอความคุ้มครองต่ออัลลอฮ์ แท้จริงพระองค์เป็นผู้ทรงได้ยิน ผู้ทรงรอบรู้ 7:200
- แท้จริงบรรดาผู้ศรัทธาคือผู้ที่เมื่ออัลลอฮ์ถูกกล่าวถึงแล้ว หัวใจของพวกเขาก็หวั่นกลัว และเมื่อโองการทั้งหลายของพระองค์ถูกอ่านแก่พวกเขา โองการเหล่านั้นก็เพิ่มพูนการศรัทธาของพวกเขา 8:2
- อย่าทรยศต่ออัลลอฮ์และรอซูลของพระองค์ และอย่าทรยศต่อความไว้วางใจของพวกท่านโดยเจตนา 8:27
- หากพวกท่านยำเกรงอัลลอฮ์และปฏิบัติตามพระองค์ พระองค์จะทรงประทานหลักเกณฑ์แก่พวกท่าน (ที่ช่วยให้แยกแยะระหว่างถูกและผิด) 8:29
- แท้จริงบรรดาผู้ปฏิเสธศรัทธานั้น พวกเขาใช้จ่ายทรัพย์สินของพวกเขาเพื่อขัดขวางผู้คนจากหนทางของอัลลอฮ์ และพวกเขาก็จะยังคงใช้จ่ายมันต่อไป แต่ภายหลังมันจะกลายเป็นความเศร้าโศกเสียใจแก่พวกเขา 8:36
- จงกล่าวแก่บรรดาผู้ปฏิเสธศรัทธา หากพวกเขาหยุด พวกเขาจะได้รับการอภัยในสิ่งที่ได้ล่วงเลยไปแล้ว แต่หากพวกเขากลับมากระทำอีก แน่นอนตัวอย่างของผู้คนรุ่นก่อน ๆ ได้ผ่านพ้นไปแล้ว 8:38
- เมื่อพวกท่านพบกับกองกำลังข้าศึก จงยืนหยัดอย่างมั่นคงและจงรำลึกถึงพระนามของอัลลอฮ์ให้มาก เพื่อพวกท่านจะได้รับชัยชนะ 8:45
- อย่าเป็นเช่นผู้ที่ออกมาจากบ้านของพวกเขาอย่างองอาจและโอ้อวดเพื่อให้ผู้คนเห็น และขัดขวางจากหนทางของอัลลอฮ์ 8:47
- แท้จริงอัลลอฮ์จะไม่ทรงเปลี่ยนแปลงความโปรดปรานที่พระองค์ประทานแก่กลุ่มชนใด จนกว่าพวกเขาจะเปลี่ยนแปลงสิ่งที่อยู่ในตัวของพวกเขาเอง 8:53
- แท้จริงสัตว์ที่เลวร้ายที่สุดในสายพระเนตรของอัลลอฮ์คือบรรดาผู้ปฏิเสธศรัทธา 8:55
- อัลลอฮ์ทรงสร้างความรักและความผูกพันขึ้นระหว่างหัวใจของผู้ที่ศรัทธาต่อพระองค์ 8:63
- จงปกป้องและช่วยเหลือผู้ที่ขอความคุ้มครอง 9:6
- ไม่เป็นการสมควรแก่บรรดามุชริกีนที่จะดูแลมัสยิดของอัลลอฮ์ 9:17
- พวกเขาต้องการจะดับแสงของอัลลอฮ์ด้วยปากของพวกเขา แต่อัลลอฮ์ไม่ทรงยอม except that His Light should be perfected even though the disbelievers hate it. 9:32
- แท้จริงซะกาตนั้นสำหรับบรรดาผู้ยากจน ผู้ขัดสน ผู้ที่ทำงานเก็บรวบรวมมัน ผู้ที่หัวใจถูกทำให้ใกล้ชิด (อิสลาม) การไถ่ทาส ลูกหนี้ และในหนทางของอัลลอฮ์ และผู้เดินทาง 9:60
- ผู้ใดต่อต้านอัลลอฮ์และรอซูลของพระองค์ แน่นอนสำหรับเขาคือนรกญะฮันนัม โดยพำนักอยู่ในนั้นตลอดกาล นั่นคือความอัปยศอย่างใหญ่หลวง 9:63
- บรรดามุนาฟิกทั้งชายและหญิงนั้นต่างก็เหมือนกัน พวกเขาต่างลืมอัลลอฮ์ พระองค์ก็ทรงลืมพวกเขา 9:67
- จงมุ่งมั่นเพื่อความบริสุทธิ์ จงเคารพความศักดิ์สิทธิ์ของมัสยิด 9:108
- ไม่เป็นการสมควรแก่ศาสดาและบรรดาผู้ศรัทธาที่จะขออภัยโทษให้แก่บรรดามุชริกีน แม้ว่าพวกเขาจะเป็นญาติใกล้ชิดก็ตาม หลังจากที่ได้ปรากฏแก่พวกเขาอย่างชัดแจ้งว่า แท้จริงพวกเขาเป็นชาวนรก 9:113
- ใครเล่าจะอธรรมยิ่งกว่าผู้ที่อุปโลกน์ความเท็จให้แก่อัลลอฮ์ หรือปฏิเสธโองการทั้งหลายของพระองค์ แท้จริงบรรดาผู้กระทำผิดจะไม่ได้รับชัยชนะ 10:17
- พวกเขาเคารพสักการะอื่นจากอัลลอฮ์ สิ่งที่มิได้ให้โทษและมิได้ให้ประโยชน์แก่พวกเขา และพวกเขากล่าวว่า เหล่านี้คือผู้ช่วยเหลือของเราต่อหน้าอัลลอฮ์ จงกล่าวเถิด พวกท่านจะแจ้งข่าวแก่อัลลอฮ์ในสิ่งที่พระองค์ไม่ทรงรู้หรือในชั้นฟ้าทั้งหลายและแผ่นดิน พระองค์ทรงบริสุทธิ์และทรงสูงส่งเหนือสิ่งที่พวกเขาตั้งภาคี 10:18
- การตอบแทนความชั่วก็คือความชั่วเช่นเดียวกัน 10:27
- นั่นคืออัลลอฮ์พระเจ้าผู้ทรงสัตย์จริงของพวกท่าน ดังนั้นหลังจากความจริงแล้ว อะไรเล่าจะเป็นอื่นไปนอกจากความหลงผิด แล้วทำไมพวกท่านจึงถูกหันเหออกไป? 10:32
- ส่วนใหญ่ของพวกเขามิได้ปฏิบัติตามสิ่งใดนอกจากความนึกคิด แท้จริงความนึกคิดนั้นไม่สามารถแทนที่ความจริงได้แต่ประการใด 10:36
- แท้จริงอัลลอฮ์นั้นมิได้ทรงอธรรมต่อมนุษย์แต่อย่างใด แต่มนุษย์ต่างหากที่อธรรมต่อตนเอง 10:44
- จงรู้เถิดว่าความโปรดปรานของพระเจ้านั้นดีกว่าสิ่งใด ๆ ที่มนุษย์สามารถสะสมหรือกักตุนไว้ 10:58
- อย่าเป็นผู้หนึ่งที่ปฏิเสธโองการทั้งหลายของอัลลอฮ์ แล้วพวกท่านจะกลายเป็นผู้ขาดทุน 10:95
- หากอัลลอฮ์ทรงให้ความทุกข์ยากแก่เจ้าแล้ว ก็ไม่มีผู้ใดจะปลดเปลื้องมันได้นอกจากพระองค์ และหากพระองค์ทรงประสงค์ความดีแก่เจ้าแล้ว ก็ไม่มีผู้ใดจะตอบแทนความโปรดปรานของพระองค์ได้ พระองค์จะทรงให้ความโปรดปรานนั้นแก่ผู้ที่พระองค์ทรงประสงค์จากปวงบ่าวของพระองค์ 10:107
- ไม่มีสัตว์เลี้ยงใด ๆ ในแผ่นดินเว้นแต่อัลลอฮ์จะเป็นผู้ประทานปัจจัยยังชีพของมัน และพระองค์ทรงรู้ที่พักพิงของมันและที่เก็บรักษาของมัน 11:6
- และหากเราให้มนุษย์ได้ลิ้มรสความเมตตาจากเรา แล้วเราได้ปลิดมันไปจากเขา แน่นอนเขาก็จะหมดหวังและเนรคุณ 11:9
- ผู้ใดปรารถนาชีวิตในโลกนี้และความหรูหราของมัน เราก็จะตอบแทนพวกเขาอย่างครบถ้วนในโลกนี้โดยไม่ลดหย่อน 11:15
- และเราไม่ได้อธรรมต่อพวกเขา แต่ว่าพวกเขาต่างหากที่อธรรมต่อตนเอง ดังนั้นบรรดาพระเจ้าที่พวกเขาวิงวอนขออื่นจากอัลลอฮ์นั้น มิได้ช่วยเหลือพวกเขาแต่อย่างใด เมื่อพระบัญชาของพระเจ้าของท่านได้มาถึง และมันไม่ได้เพิ่มสิ่งใดแก่พวกเขานอกจากการพินาศ 11:101
- ในวันที่มันมาถึง ไม่มีผู้ใดจะพูดได้เว้นแต่ได้รับอนุมัติจากพระองค์ ในหมู่พวกเขานั้นมีผู้เป็นทุกข์และผู้เป็นสุข 11:105
- ส่วนบรรดาผู้เป็นทุกข์นั้น พวกเขาจะอยู่ในนรก มีแต่การถอนหายใจและการสะอื้น 11:106
- พวกเขาจะอยู่ในนั้นตลอดกาลตราบเท่าที่ชั้นฟ้าทั้งหลายและแผ่นดินยั่งยืน เว้นแต่พระเจ้าของเจ้าทรงประสงค์เป็นอย่างอื่น แท้จริงพระเจ้าของเจ้าทรงกระทำสิ่งที่พระองค์ทรงประสงค์ 11:107
- ส่วนบรรดาผู้เป็นสุขนั้น พวกเขาจะอยู่ในสวนสวรรค์ตลอดกาลตราบเท่าที่ชั้นฟ้าทั้งหลายและแผ่นดินยั่งยืน เว้นแต่พระเจ้าของเจ้าทรงประสงค์เป็นอย่างอื่น เป็นการประทานที่ไม่มีที่สิ้นสุด 11:108
- อย่าโอนเอียงไปทางผู้ที่อธรรม มิฉะนั้นไฟนรกจะลงโทษพวกท่าน และพวกท่านจะไม่มีผู้คุ้มครองอื่นใดนอกจากอัลลอฮ์ แล้วพวกท่านก็จะไม่ได้รับความช่วยเหลือ 11:113
- จงดำรงไว้ซึ่งการละหมาดทั้งสองปลายของวันและยามใกล้รุ่งอรุณ แท้จริงความดีทั้งหลายนั้นจะขจัดความชั่วทั้งหลายออกไป นั่นคือข้อเตือนใจสำหรับผู้ที่รำลึก 11:114
- และเฉพาะอัลลอฮ์เท่านั้นคือสิ่งที่พ้นญาณในชั้นฟ้าทั้งหลายและแผ่นดิน และทุกเรื่องราวจะถูกนำกลับไปสู่พระองค์ 11:123
- การตัดสินนั้นเป็นสิทธิของอัลลอฮ์แต่เพียงผู้เดียว พระองค์ทรงบัญชาให้พวกท่านเคารพภักดีต่อพระองค์เท่านั้น นั่นคือศาสนาอันเที่ยงตรง แต่ส่วนใหญ่ของมนุษย์ไม่รู้ 12:40
- อย่าสิ้นหวังต่อความเมตตาของอัลลอฮ์ 12:87
- และส่วนใหญ่ของมนุษย์จะไม่ศรัทธา แม้เจ้าจะปรารถนาอย่างยิ่งก็ตาม 12:103
- และส่วนใหญ่ของพวกเขาจะไม่ศรัทธาต่ออัลลอฮ์ เว้นแต่พวกเขาจะตั้งภาคีขึ้น 12:106
- อัลกุรอานมิใช่คำกล่าวที่ถูกปั้นแต่งขึ้น แต่เป็นการยืนยันคัมภีร์ที่มีมาก่อน และเป็นการอธิบายทุกสิ่งอย่างโดยละเอียด และเป็นแนวทางและความเมตตาแก่หมู่ชนผู้ศรัทธา 12:111
- อัลลอฮ์ทรงเพิ่มพูนปัจจัยยังชีพแก่ผู้ที่พระองค์ทรงประสงค์ และทรงให้คับแคบแก่ผู้ที่พระองค์ทรงประสงค์ 13:26
- จงรำลึกถึงอัลลอฮ์อย่างมากมายผ่านการรำลึก (ซิกิรฺ) แท้จริงผู้ที่ศรัทธาต่อพระเจ้านั้นหัวใจของพวกเขาจะสงบด้วยการรำลึกถึงพระองค์ 13:28
- บรรดาผู้ศรัทธาและกระทำความดีทั้งหลาย จะได้รับความสุขและความปลาบปลื้ม 13:29
- บรรดาผู้ที่เลือกเอาชีวิตในโลกนี้แทนปรโลก และขัดขวางผู้คนจากหนทางของอัลลอฮ์ และต้องการให้หนทางนั้นคดเคี้ยว พวกเขาอยู่ในการหลงผิดอันห่างไกล 14:3
- จงปฏิบัติตนด้วยความอ่อนน้อมและกตัญญูในการเคารพภักดี 14:7
- อุปมาผู้ที่ปฏิเสธศรัทธาต่อพระเจ้าของพวกเขา คือบรรดาการงานของพวกเขาประดุจเถ้าถ่านที่ถูกลมพัดอย่างแรงในวันที่มีพายุ พวกเขาไม่สามารถได้อะไรจากสิ่งที่พวกเขาแสวงหาไว้ 14:18
- อัลลอฮ์จะทรงให้บรรดาผู้ศรัทธาหมั้นคงอยู่ด้วยคำกล่าวที่มั่นคงทั้งในโลกนี้และโลกหน้า 14:27
- และเจ้าอย่าคิดว่าอัลลอฮ์ทรงเพิกเฉยต่อสิ่งที่บรรดาผู้อธรรมปฏิบัติ แต่พระองค์ทรงประวิงเวลาให้พวกเขาจนถึงวันที่สายตาจะจ้องจับจับ 14:42
- เพื่ออัลลอฮ์จะได้ทรงตอบแทนทุกชีวิตตามที่มันได้แสวงหาไว้ แท้จริงอัลลอฮ์นั้นทรงเป็นผู้รวดเร็วในการชำระสอบสวน 14:51
- และเราได้สร้างมนุษย์จากดินแห้งที่ส่งเสียงดัง จากดินดำที่เปลี่ยนสภาพ 15:26
- และญินนั้นเราได้สร้างมันมาก่อนจากไฟที่ร้อนแรง 15:27
- มันมีประตูเจ็ดประตู สำหรับทุกประตูมีส่วนแบ่งที่ถูกจัดไว้ 15:44
- พระองค์ทรงสร้างมนุษย์จากน้ำกาม จากนั้นเขาก็เป็นปฏิปักษ์ที่ชัดแจ้ง 16:4
- และปศุสัตว์ พระองค์ทรงสร้างมันเพื่อพวกท่าน ในนั้นมีความอบอุ่นและประโยชน์มากมาย และบางส่วนจากมันพวกท่านก็กินได้ 16:5
- และพระองค์ทรงสร้างม้า ล่อ และลา เพื่อให้พวกท่านขี่และเป็นเครื่องประดับ และพระองค์ทรงสร้างสิ่งอื่น ๆ ที่พวกท่านไม่รู้ 16:8
- พระองค์คือผู้ทรงหลั่งน้ำลงมาจากฟากฟ้า เพื่อให้พวกท่านดื่ม และเพื่อให้พืชพันธุ์งอกงาม ซึ่งพวกท่านใช้เลี้ยงปศุสัตว์ 16:10
- พระองค์คือผู้ทรงทำให้ทะเลเป็นประโยชน์ เพื่อพวกท่านจะได้กินเนื้อสดจากมัน และพวกท่านจะได้นำเอาประดับประดาจากมันมาใช้ 16:14
- พระองค์ทรงวางภูเขามั่นคงในแผ่นดิน เพื่อมิให้มันเคลื่อนไหวไปกับพวกท่าน และทรงวางแม่น้ำและหนทาง เพื่อพวกท่านจะได้พบทาง 16:15
- ดังนั้นผู้ทรงสร้างจะเหมือนกับผู้ที่ไม่ทรงสร้างหรือ? พวกท่านมิได้ใคร่ครวญดอกหรือ? 16:17
- และหากพวกท่านจะนับความโปรดปรานของอัลลอฮ์ พวกท่านก็ไม่สามารถจะนับมันได้ 16:18
- และอัลลอฮ์ทรงรู้สิ่งที่พวกท่านปกปิดและสิ่งที่พวกท่านเปิดเผย 16:19
- และบรรดาสิ่งที่พวกเขาวิงวอนขออื่นจากอัลลอฮ์นั้น มิได้สร้างสิ่งใดเลย แต่พวกมันถูกสร้างขึ้นมา 16:20
- พวกมันตายแล้ว ไม่มีชีวิต และพวกมันไม่รู้ว่าพวกมันจะถูกฟื้นคืนชีพเมื่อใด 16:21
- แท้จริงบัญชาของเราเมื่อเราประสงค์สิ่งใด เราจะกล่าวแก่มันว่า “จงเป็น” แล้วมันก็จะเป็นขึ้นมา 16:40
